#[derive(Component)]
pub struct ModalRoot;
#[derive(Component)]
pub struct ModalText;

fn letter_index(k: KeyCode) -> Option<usize> {
    use KeyCode::*;
    Some(match k {
        KeyA => 0,
        KeyB => 1,
        KeyC => 2,
        KeyD => 3,
        KeyE => 4,
        KeyF => 5,
        KeyG => 6,
        KeyH => 7,
        KeyI => 8,
        KeyJ => 9,
        KeyK => 10,
        KeyL => 11,
        KeyM => 12,
        KeyN => 13,
        KeyO => 14,
        KeyP => 15,
        KeyQ => 16,
        KeyR => 17,
        KeyS => 18,
        KeyT => 19,
        KeyU => 20,
        KeyV => 21,
        KeyW => 22,
        KeyX => 23,
        KeyY => 24,
        KeyZ => 25,
        _ => return None,
    })
}

/// Pack entries matching a tval filter, as (pack index, item).
fn pack_tval(inv: &Inventory, gd: &GameData, tval: i32) -> Vec<(usize, usize)> {
    inv.pack
        .iter()
        .enumerate()
        .filter(|(_, it)| gd.objects[it.def].tval == tval)
        .map(|(i, it)| (i, it.def))
        .collect()
}

/// Rod tips and rod mains, both usable with the 'Z' command
/// (cmd6.cc item_tester_hook_zapable).
fn rod_entries(inv: &Inventory, gd: &GameData) -> Vec<(usize, usize)> {
    pack_tvals(inv, gd, &[data::TV_ROD, data::TV_ROD_MAIN])
}

/// Rod mains still waiting for a tip (cmd6.cc item_tester_hook_attachable).
fn attachable_rods(inv: &Inventory, gd: &GameData) -> Vec<(usize, usize)> {
    inv.pack
        .iter()
        .enumerate()
        .filter(|(_, it)| gd.objects[it.def].tval == data::TV_ROD_MAIN && it.pval == 0)
        .map(|(i, it)| (i, it.def))
        .collect()
}

/// Pack entries matching any of the given tvals, as (pack index, item).
fn pack_tvals(inv: &Inventory, gd: &GameData, tvals: &[i32]) -> Vec<(usize, usize)> {
    inv.pack
        .iter()
        .enumerate()
        .filter(|(_, it)| tvals.contains(&gd.objects[it.def].tval))
        .map(|(i, it)| (i, it.def))
        .collect()
}

/// Short name of an action mkey (src/defines.hpp MKEY_*).
fn action_name(mkey: i32) -> &'static str {
    match mkey {
        0 => "melee mode",
        2 => "mindcraft",
        3 => "antimagic",
        6 => "mimicry",
        7 => "necromancy",
        8 => "power mage",
        10 => "ammo creation",
        11 => "possession",
        13 => "summoning",
        15 => "stealing",
        16 => "dodge",
        17 => "cast a spell",
        19 => "copy spell",
        20 => "symbiosis",
        21 => "boulder",
        22 => "companion",
        23 => "piercing shots",
        100 => "touch of death",
        101 => "geomancy",
        102 => "far reaching",
        _ => "action",
    }
}

/// The activatable action list: developed skills with an action mkey plus
/// known abilities with one (skills.cc do_cmd_activate_skill_aux).
fn action_list(ps: &PlayerState, gd: &GameData) -> Vec<(i32, String)> {
    let mut out: Vec<(i32, String)> = Vec::new();
    let (melee, _) = crate::skill::get_melee_skills(ps);
    if melee > 1 {
        out.push((0, "Change melee mode".to_string()));
    }
    let mut skills: Vec<&data::SkillDef> = gd
        .skills
        .iter()
        .filter(|s| {
            s.action_mkey != 0
                && ps.skill_value(s.id) != 0
                && (!ps.skill_hidden.contains(&s.id) || s.id == crate::skill::SK_LEARN)
        })
        .collect();
    skills.sort_by_key(|s| s.id);
    for s in skills {
        if s.action_desc.is_empty() {
            continue;
        }
        if out.iter().any(|(m, _)| *m == s.action_mkey) {
            continue;
        }
        out.push((s.action_mkey, s.action_desc.clone()));
    }
    let mut abs: Vec<&data::AbilityDef> = gd
        .abilities
        .iter()
        .filter(|a| a.action_mkey != 0 && ps.has_ability(a.id))
        .collect();
    abs.sort_by(|a, b| crate::skill::compare_abilities(a, b));
    for a in abs {
        if out.iter().any(|(m, _)| *m == a.action_mkey) {
            continue;
        }
        out.push((a.action_mkey, a.action_desc.clone()));
    }
    out
}

/// Execute an action chosen in the Actions screen (skills.cc
/// do_cmd_activate_skill switch).
fn use_action(ctx: &mut ModalCtx, mkey: i32) {
    match mkey {
        17 => {
            // Cast a spell (MKEY_SCHOOL): the normal cast screen.
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log.add("An antimagic field prevents spellcasting!");
            } else if crate::spell::known_spells(&ctx.gd, &ctx.ps).is_empty() {
                ctx.log.add("You cannot cast spells.");
            } else {
                *ctx.modal = Modal::Cast;
            }
            return;
        }
        2 => {
            // Mindcraft powers (cmd7.cc do_cmd_mindcraft).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            if ctx.ps.confuse > 0 {
                ctx.log.add("You are too confused!");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Mindcraft { cursor: 0 };
        }
        3 => {
            // Disrupt continuum / destroy doors (cmd7.cc do_cmd_unbeliever).
            *ctx.modal = Modal::Antimagic;
        }
        7 => {
            // Necromancy powers (cmd7.cc do_cmd_necromancer).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            if ctx.ps.confuse > 0 {
                ctx.log.add("You are too confused!");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Necromancy { cursor: 0 };
        }
        8 => {
            // Power Mage random spells (cmd7.cc do_cmd_powermage).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Thaumaturgy { cursor: 0 };
        }
        101 => {
            // Geomancy: needs a magestaff and a point in each element
            // (spells6.cc geomancy_depends_satisfied).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            let staff = ctx.inv.equip[data::SLOT_WEAPON]
                .as_ref()
                .map(|it| ctx.gd.objects[it.def].tval == data::TV_MSTAFF)
                .unwrap_or(false);
            if !staff {
                ctx.log.add("You must wield a magestaff to use Geomancy.");
                close(ctx);
                return;
            }
            let missing = [
                crate::skill::SK_FIRE,
                crate::skill::SK_AIR,
                crate::skill::SK_EARTH,
                crate::skill::SK_WATER,
            ]
            .iter()
            .any(|s| ctx.ps.skill(*s) <= 0);
            if missing {
                ctx.log
                    .add("You must have some skill in all four elements.");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Geomancy { cursor: 0 };
        }
        15 => {
            // Stealing: first pick the monster (cmd2.cc do_cmd_steal
            // asks for a direction).
            *ctx.modal = Modal::Target(PendingTarget {
                name: "stealing".to_string(),
                kind: "steal".to_string(),
                arg: String::new(),
                device: None,
            });
        }
        6 => {
            // Mimicry powers (MKEY_MIMIC / cmd7.cc do_cmd_mimic).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            if ctx.ps.confuse > 0 {
                ctx.log.add("You are too confused!");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::MimicPower { cursor: 0 };
        }
        19 => {
            // Copy a known spell into an empty SPELL_CONTAIN item
            // (cmd5.cc do_cmd_copy_spell).
            let has_container = ctx.inv.pack.iter().any(|it| {
                it.spells.is_empty()
                    && item::item_flags(&ctx.gd, it)
                        .iter()
                        .any(|f| *f == "SPELL_CONTAIN")
            });
            if !has_container {
                ctx.log
                    .add("You have no empty spell container to copy into.");
                close(ctx);
                return;
            }
            if spell::known_spells_with_books(&ctx.gd, &ctx.ps, &ctx.inv).is_empty() {
                ctx.log.add("You know no spells to copy.");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::CopySpell {
                cursor: 0,
                spell: None,
            };
        }
        0 => {
            // Cycle to the next developed style (skills.cc choose_melee).
            let Some((next, name)) = crate::skill::next_melee_style(&ctx.ps) else {
                close(ctx);
                return;
            };
            let name = name.to_string();
            if next == ctx.ps.melee_style {
                ctx.log.add(format!("You are already using {}.", name));
                close(ctx);
                return;
            }
            // choose_melee (skills.cc:777): strip both weapon slots first.
            // A cursed weapon stops the strip with the original message
            // (the style still changes, exactly like the C++).
            for slot in [data::SLOT_WEAPON, data::SLOT_WEAPON2] {
                let Some(it) = ctx.inv.equip[slot].as_ref() else {
                    continue;
                };
                if it.cursed {
                    ctx.log.add(format!(
                        "Hmmm, your {} seems to be cursed.",
                        it.label(&ctx.gd, &ctx.inv.known)
                    ));
                    break;
                }
                let it = ctx.inv.equip[slot].take().expect("worn");
                ctx.log.add(format!(
                    "You take off {}.",
                    it.label(&ctx.gd, &ctx.inv.known)
                ));
                let d = item::stat_deltas(&ctx.gd, &it);
                for i in 0..6 {
                    ctx.ps.stats[i] -= d[i];
                }
                ctx.inv.pack.push(it);
            }
            ctx.ps.ac = game::player_ac(&ctx.ps, &ctx.inv, &ctx.gd);
            ctx.ps.melee_style = next;
            ctx.log.add(format!("You now use {}.", name));
            consume_turn(ctx);
            close(ctx);
        }
        10 => {
            // Ammo creation (cmd7.cc do_cmd_archer): shots need a rubble
            // pile, arrows/bolts convert one junk/skeleton item.
            if ctx.ps.confuse > 0 || ctx.ps.blind > 0 {
                ctx.log.add("You are in no state to forge ammo.");
                close(ctx);
                return;
            }
            let archery = ctx.ps.skill(crate::skill::SK_ARCHERY);
            let mut opts = "Create [S]hots".to_string();
            if archery >= 10 {
                opts.push_str(" or [A]rrows");
            }
            if archery >= 20 {
                opts.push_str(" or [B]olts");
            }
            ctx.log.add(format!("{}?", opts));
            *ctx.modal = Modal::ForgeAmmo { archery };
        }
        16 => {
            let chance = game::dodge_chance(&ctx.ps, &ctx.inv, &ctx.gd);
            ctx.log.add(format!("Your dodge chance is {}.", chance));
            close(ctx);
        }
        11 => {
            // Possessor race powers / incarnating (cmd7.cc
            // do_cmd_possessor).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Possessor;
        }
        13 => {
            // Summoner totems (cmd7.cc do_cmd_summoner).
            if ctx.inv.totals_for(&ctx.gd, &ctx.ps).no_magic
                || ctx.ps.skill(crate::skill::SK_ANTIMAGIC) > 0
            {
                ctx.log
                    .add("Your anti-magic field disrupts any magic attempts.");
                close(ctx);
                return;
            }
            if ctx.ps.confuse > 0 {
                ctx.log.add("You are too confused!");
                close(ctx);
                return;
            }
            if ctx.ps.blind > 0 {
                ctx.log.add("You cannot see!");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Summon;
        }
        21 => {
            // Create boulders out of an adjacent granite wall
            // (cmd7.cc do_cmd_create_boulder).
            *ctx.modal = Modal::Target(PendingTarget {
                name: "boulder".to_string(),
                kind: "boulder".to_string(),
                arg: String::new(),
                device: None,
            });
        }
        20 => {
            if ctx.inv.equip[data::SLOT_SYMBIOTE].is_none() {
                ctx.log.add("You are not in symbiosis.");
                close(ctx);
            } else {
                *ctx.modal = Modal::Symbiosis { cursor: 0 };
            }
        }
        22 => {
            if ctx.ps.skill(crate::skill::SK_LORE) < 12 {
                ctx.log.add("You need a skill level of at least 12.");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Target(PendingTarget {
                name: "companion".to_string(),
                kind: "companion".to_string(),
                arg: String::new(),
                device: None,
            });
        }
        23 => {
            if ctx.ps.skill(crate::skill::SK_BOW) <= 25
                && ctx.ps.skill(crate::skill::SK_XBOW) <= 25
                && ctx.ps.skill(crate::skill::SK_SLING) <= 25
            {
                ctx.log.add("You can't fire piercing shots yet.");
            } else {
                ctx.ps.piercing = !ctx.ps.piercing;
                ctx.log.add(if ctx.ps.piercing {
                    "Piercing shots activated."
                } else {
                    "Piercing shots deactivated."
                });
            }
            close(ctx);
        }
        100 => {
            // Touch of death: 40 mana, a 30-tile ray of instant death
            // (skills.cc MKEY_DEATH_TOUCH).
            if !ctx.ps.has_ability(crate::skill::AB_TOUCH_OF_DEATH) {
                close(ctx);
                return;
            }
            if ctx.ps.mana <= 40 {
                ctx.log.add("You need at least 40 mana.");
                close(ctx);
                return;
            }
            ctx.ps.mana -= 40;
            *ctx.modal = Modal::Target(PendingTarget {
                name: "touch of death".to_string(),
                kind: "death_touch".to_string(),
                arg: String::new(),
                device: None,
            });
        }
        102 => {
            let ok = ctx.inv.equip[data::SLOT_WEAPON]
                .as_ref()
                .map(|it| ctx.gd.objects[it.def].tval == data::TV_POLEARM)
                .unwrap_or(false);
            if !ok {
                ctx.log.add("You will need a long polearm for this!");
                close(ctx);
                return;
            }
            *ctx.modal = Modal::Target(PendingTarget {
                name: "far reaching attack".to_string(),
                kind: "reach".to_string(),
                arg: String::new(),
                device: None,
            });
        }
        _ => {
            ctx.log.add(format!(
                "{} is not yet implemented in this port.",
                action_name(mkey)
            ));
            close(ctx);
        }
    }
}

/// Toggle the continuum disruption field (cmd7.cc
/// do_cmd_unbeliever_antimagic); requires Antimagic 20.
fn antimagic_toggle(ctx: &mut ModalCtx) {
    if ctx.ps.skill(crate::skill::SK_ANTIMAGIC) < 20 {
        ctx.log.add(
            "You must have at least a level 20 antimagic skill to be able to \
             disrupt the magic continuum.",
        );
        return;
    }
    ctx.ps.antimagic_field = !ctx.ps.antimagic_field;
    ctx.log.add(if ctx.ps.antimagic_field {
        "You start disrupting the magic continuum."
    } else {
        "You stop disrupting the magic continuum."
    });
}

/// Destroy every door in the 3x3 around the player (spells2.cc
/// destroy_doors_touch: GF_KILL_DOOR project radius 1); needs Antimagic 25.
fn destroy_doors_touch(ctx: &mut ModalCtx) {
    if ctx.ps.skill(crate::skill::SK_ANTIMAGIC) < 25 {
        ctx.log
            .add("You cannot use your door destruction abilities yet.");
        return;
    }
    let Ok(pos) = ctx.player.single() else {
        return;
    };
    let (px, py) = (pos.x, pos.y);
    let mut flash = false;
    for dy in -1..=1 {
        for dx in -1..=1 {
            let (x, y) = (px + dx, py + dy);
            if !Map::in_bounds(x, y) {
                continue;
            }
            let t = ctx.map.terrain_at(x, y);
            // Open/broken doors and FEAT_DOOR_HEAD..FEAT_DOOR_TAIL.
            let door = t == map::T_OPEN_DOOR || t == 5 || (32..=47).contains(&t);
            if !door {
                continue;
            }
            if ctx
                .map
                .visible
                .get(Map::idx(x, y))
                .copied()
                .unwrap_or(false)
            {
                flash = true;
            }
            ctx.map.set_terrain(x, y, map::T_FLOOR);
        }
    }
    if flash {
        ctx.log.add("There is a bright flash of light!");
    }
}

/// The monster race encoded on a corpse/totem item (object1.cc uses
/// pval2; this port stores it in `note`, like corpses).
fn totem_race(it: &item::Item) -> usize {
    it.note as usize
}

/// Extract a totem from a corpse (cmd7.cc do_cmd_summoner_extract). The
/// corpse is consumed even when the extraction fails.
fn totem_extract(ctx: &mut ModalCtx, item: usize, partial: bool) {
    let mut rng = crate::rng::current();
    let race = totem_race(&ctx.inv.pack[item]);
    let Some(level) = ctx.gd.monsters.get(race).map(|d| d.depth as i32) else {
        return;
    };
    // Consume the corpse before rolling, exactly like the original.
    if ctx.inv.pack[item].count > 1 {
        ctx.inv.pack[item].count -= 1;
    } else {
        ctx.inv.pack.remove(item);
    }
    if rng.gen_range(0..100) < level - ctx.ps.skill(crate::skill::SK_SUMMON) {
        ctx.log.add("You failed to extract a totem.");
        consume_turn(ctx);
        return;
    }
    let sval = if partial { 1 } else { 2 };
    if let Some(d) = ctx.gd.object_by_tval_sval(data::TV_TOTEM, sval) {
        let mut totem = item::Item::base(&ctx.gd, d);
        totem.note = race as u32;
        totem.identified = true;
        ctx.inv.learn(d);
        ctx.inv.pack.push(totem);
        ctx.log.add("You extract a totem from the dead corpse.");
    }
    consume_turn(ctx);
}

/// Summon from a totem (cmd7.cc summon_true / do_cmd_summoner_summon).
fn totem_summon(ctx: &mut ModalCtx, item: usize) {
    let mut rng = crate::rng::current();
    let totem = ctx.inv.pack[item].clone();
    let race = totem_race(&totem);
    let (unique, level) = match ctx.gd.monsters.get(race) {
        Some(d) => (d.unique, d.depth as i32),
        None => return,
    };
    let skill = ctx.ps.skill(crate::skill::SK_SUMMON);
    let true_totem = ctx.gd.objects[totem.def].sval == 2;
    consume_turn(ctx);
    // True totems may be destroyed or turn hostile; partial ones always
    // produce a disposable pet.
    let (used, pet) = if !true_totem {
        (false, true)
    } else if unique {
        let chance = skill * 70 / (level + 1);
        (true, rng.gen_range(0..100) < chance)
    } else if skill == 0 {
        (true, false)
    } else {
        let used = rng.gen_range(0..100) < (level * 25 / skill);
        let chance = skill * 130 / (level + 1);
        (used, rng.gen_range(0..100) < chance)
    };
    // Find an empty grid within four tiles of the player.
    let Ok(pos) = ctx.player.single() else {
        return;
    };
    let (px, py) = (pos.x, pos.y);
    let occupied: HashSet<(i32, i32)> =
        ctx.monsters.iter().map(|(_, _, mp)| (mp.x, mp.y)).collect();
    let mut spot = None;
    for _ in 0..40 {
        let (rx, ry) = (px + rng.gen_range(-4..=4), py + rng.gen_range(-4..=4));
        if Map::in_bounds(rx, ry)
            && ctx.map.walkable(&ctx.gd, rx, ry)
            && !occupied.contains(&(rx, ry))
        {
            spot = Some((rx, ry));
            break;
        }
    }
    let Some((sx, sy)) = spot else {
        ctx.log.add("The summoning fails due to lack of room.");
        return;
    };
    if pet {
        if true_totem {
            game::spawn_flagged(
                &mut ctx.commands,
                &ctx.gd,
                &ctx.tiles,
                race,
                sx,
                sy,
                false,
                false,
                true,
                &mut rng,
            );
        } else {
            // Partial totems are MFLAG_PARTIAL pets (cmd7.cc).
            game::spawn_partial_pet(
                &mut ctx.commands,
                &ctx.gd,
                &ctx.tiles,
                race,
                sx,
                sy,
                &mut rng,
            );
        }
    } else {
        game::spawn_single(
            &mut ctx.commands,
            &ctx.gd,
            &ctx.tiles,
            race,
            sx,
            sy,
            false,
            false,
            &mut rng,
        );
    }
    if used {
        if ctx.inv.pack[item].count > 1 {
            ctx.inv.pack[item].count -= 1;
        } else {
            ctx.inv.pack.remove(item);
        }
    }
}

/// The carried symbiotic monster's race def, if any.
fn symbiote_def(ctx: &ModalCtx) -> Option<usize> {
    let it = ctx.inv.equip[data::SLOT_SYMBIOTE].as_ref()?;
    let def = it.note as usize;
    if def < ctx.gd.monsters.len() {
        Some(def)
    } else {
        None
    }
}

