            if lv >= 15 {
                if ctx.ps.exp_drained > 0 {
                    ctx.ps.exp += ctx.ps.exp_drained;
                    ctx.ps.exp_drained = 0;
                }
            }
            ctx.log.add("You feel recovered.");
