    #[test]
    fn knowledge_quest_page_reports_dump_hook_states() {
        let gd = load_game_data();
        let mut plot = crate::game::PlotQuest::default();
        plot.set(crate::game::PLOT_BETWEEN, crate::game::PLOT_COMPLETED);
        plot.set(crate::game::PLOT_WIGHT, crate::game::PLOT_TAKEN);
        let ps = crate::birth::make_player(&gd, "K".into(), 0, 0);
        let text = knowledge_text(
            7,
            0,
            &ps,
            &gd,
            &plot,
            &crate::item::CreatedArtifacts::default(),
            "",
            "",
        );
        // The q_*.cc chardump hooks' state is the knowledge quest page.
        assert!(text.contains("the Between Completed - Unrewarded"), "{text}");
        assert!(text.contains("the Wights' Grave"), "{text}");
        // quest_bounty_describe names the wanted corpse.
        plot.bounty = Some((0, false));
        let bounty_text = knowledge_text(
            7,
            0,
            &ps,
            &gd,
            &plot,
            &crate::item::CreatedArtifacts::default(),
            "",
            "",
        );
        assert!(bounty_text.contains("Bounty quest!"), "{bounty_text}");
        assert!(
            bounty_text.contains(&format!("{} corpse", gd.monsters[0].name)),
            "{bounty_text}"
        );
        // The default plot already carries the taken Necromancer quest.
        let default_plot = knowledge_text(
            7,
            0,
            &ps,
            &gd,
            &crate::game::PlotQuest::default(),
            &crate::item::CreatedArtifacts::default(),
            "",
            "",
        );
        assert!(
            default_plot.contains("the Necromancer of Dol Guldur"),
            "{default_plot}"
        );
    }

    #[test]
    fn follow_god_and_may_follow_god_follow_gods_cc() {
        let gd = load_game_data();
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        let mut inv = Inventory::default();
        // may_follow_god (gods.cc:59): only Melkor rejects a Ring bearer.
        assert!(may_follow_god(&ps, &inv, 4));
        ps.ring_worn = true;
        assert!(!may_follow_god(&ps, &inv, 4));
        assert!(may_follow_god(&ps, &inv, 5), "only Melkor minds the Ring");
        ps.ring_worn = false;
        // An equipped ART_POWER (13) is just as corrupting.
        let mut ring = crate::item::Item::base(&gd, 0);
        ring.artifact = 13;
        inv.equip[crate::data::SLOT_WEAPON] = Some(ring);
        assert!(!may_follow_god(&ps, &inv, 4));
        inv.equip[crate::data::SLOT_WEAPON] = None;
        // follow_god: antimagic disbelief refuses.
        ps.skills
            .insert(crate::skill::SK_ANTIMAGIC, crate::skill::SKILL_STEP);
        assert!(follow_god(&mut ps, &inv, 4).is_some());
        assert_eq!(ps.god, 0);
        ps.skills.remove(&crate::skill::SK_ANTIMAGIC);
        // The Ring rejects Melkor.
        ps.ring_worn = true;
        assert!(follow_god(&mut ps, &inv, 4).is_some());
        ps.ring_worn = false;
        // Adoption only while godless (pgod == GOD_NONE).
        assert!(follow_god(&mut ps, &inv, 4).is_none());
        assert_eq!(ps.god, 4);
        assert!(follow_god(&mut ps, &inv, 1).is_some());
        assert_eq!(ps.god, 4, "the old god is not overwritten");
    }

