    #[test]
    fn symbol_browser_filters_unique_and_name() {
        let gd = load_game_data();
        match symbol_browser("all", None, &gd) {
            Modal::SymbolBrowser { list, .. } => {
                assert!(list.len() > 100);
                assert!(list.iter().all(|i| *i > 0));
                assert!(list.iter().any(|i| gd.monsters[*i].unique));
                assert!(list.iter().any(|i| !gd.monsters[*i].unique));
            }
            _ => panic!("expected a SymbolBrowser"),
        }
        match symbol_browser("u", Some((true, String::new())), &gd) {
            Modal::SymbolBrowser { list, .. } => {
                assert!(!list.is_empty());
                assert!(list.iter().all(|i| gd.monsters[*i].unique));
            }
            _ => panic!("expected a SymbolBrowser"),
        }
        match symbol_browser("n", Some((false, "spider".to_string())), &gd) {
            Modal::SymbolBrowser { list, .. } => {
                assert!(!list.is_empty());
                assert!(list
                    .iter()
                    .all(|i| gd.monsters[*i].name.to_lowercase().contains("spider")));
            }
            _ => panic!("expected a SymbolBrowser"),
        }
    }

    #[test]
    fn monster_power_lists_filter_great_and_unknown() {
        let gd = load_game_data();
        let fire = gd
            .monsters
            .iter()
            .find(|m| m.spells.iter().any(|s| s == "BR_FIRE"))
            .expect("a fire breather");
        let minor = monster_power_list(fire, false);
        let major = monster_power_list(fire, true);
        assert!(minor.iter().any(|(f, _)| *f == "BR_FIRE"));
        assert!(major.len() >= minor.len());
        // A great power (BR_POIS) never appears in the minor list.
        let pois = gd
            .monsters
            .iter()
            .find(|m| m.spells.iter().any(|s| s == "BR_POIS"))
            .expect("a poison breather");
        assert!(monster_power_list(pois, false)
            .iter()
            .all(|(f, _)| *f != "BR_POIS"));
        assert!(monster_power_list(pois, true)
            .iter()
            .any(|(f, _)| *f == "BR_POIS"));
        // Flags without a power entry (e.g. DRAIN_MANA) are ignored.
        assert!(!major.iter().any(|(f, _)| *f == "DRAIN_MANA"));
    }

    #[test]
    fn action_list_dedups_mkeys_and_offers_melee_choice() {
        let gd = load_game_data();
        let mage = gd.classes.iter().position(|c| c.name == "Mage").unwrap();
        let mut ps = crate::birth::make_player(&gd, "M".into(), 0, mage);
        // Magic, Mana and other schools all share mkey 17: one entry.
        let list = action_list(&ps, &gd);
        assert_eq!(list.iter().filter(|(m, _)| *m == 17).count(), 1);
        assert!(list
            .iter()
            .any(|(m, d)| *m == 17 && d == "Cast a spell"));
        // A single melee style offers no "Change melee mode" (mkey 0).
        assert!(!list.iter().any(|(m, _)| *m == 0));
        ps.skills.insert(crate::skill::SK_HAND, crate::skill::SKILL_STEP);
        let list = action_list(&ps, &gd);
        assert!(list
            .iter()
            .any(|(m, d)| *m == 0 && d == "Change melee mode"));
        // Known abilities with an action mkey are listed too.
        let mut rogue = crate::birth::make_player(
            &gd,
            "R".into(),
            0,
            gd.classes.iter().position(|c| c.name == "Rogue").unwrap(),
        );
        rogue.abilities.push(crate::skill::AB_AMMO_CREATION);
        let list = action_list(&rogue, &gd);
        assert!(list.iter().any(|(m, _)| *m == 10));
    }

    #[test]
    fn stores_only_buy_their_kinds() {
        let gd = load_game_data();
        let store = |name: &str| gd.stores.iter().find(|s| s.name == name).unwrap();
        let food = gd.object_by_name("Ration of Food").expect("food");
        let boots = gd
            .object_by_name("Pair of Soft Leather Boots")
            .expect("boots");
        let sword = gd.object_by_name("Long Sword").expect("sword");
        let food_item = crate::item::Item::base(&gd, food);
        let boots_item = crate::item::Item::base(&gd, boots);
        let sword_item = crate::item::Item::base(&gd, sword);
        assert!(store_will_buy(&gd, store("General Store"), &food_item));
        assert!(!store_will_buy(&gd, store("General Store"), &boots_item));
        assert!(store_will_buy(&gd, store("Armoury"), &boots_item));
        assert!(!store_will_buy(&gd, store("Armoury"), &food_item));
        assert!(store_will_buy(&gd, store("Weaponsmith"), &sword_item));
        assert!(!store_will_buy(&gd, store("Weaponsmith"), &boots_item));
        // The Black Market buys anything.
        assert!(store_will_buy(&gd, store("Black Market"), &food_item));
        // Worthless items are refused (object_value <= 0).
        if let Some(junk) = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_JUNK)
        {
            let it = crate::item::Item::base(&gd, junk);
            if it.cost(&gd) <= 0 {
                assert!(!store_will_buy(&gd, store("Black Market"), &it));
            }
        }
    }

    #[test]
    fn store_buys_random_books_blessed_gear_and_museum_donations() {
        let gd = crate::data::load_game_data();
        let store = |name: &str| gd.stores.iter().find(|s| s.name == name).unwrap();
        let random_book = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_BOOK && o.sval == 255)
            .expect("a random spellbook kind");
        let magic_idx = gd
            .spells
            .iter()
            .position(|sp| crate::spell::random_type(sp) == crate::skill::SK_MAGIC)
            .unwrap();
        let spirit_idx = gd
            .spells
            .iter()
            .position(|sp| crate::spell::random_type(sp) == crate::skill::SK_SPIRITUALITY)
            .unwrap();
        let magic_spell = gd.spells[magic_idx].name.clone();
        let spirit_spell = gd.spells[spirit_idx].name.clone();
        // BOOK_RANDOM: the Temple buys Spirituality tomes, the Magic shop
        // Magic ones (store.cc:715-782).
        let mut book = crate::item::Item::base(&gd, random_book);
        book.pval = spirit_idx as i32;
        book.spells = vec![spirit_spell.clone()];
        assert!(store_will_buy(&gd, store("Temple"), &book));
        assert!(!store_will_buy(&gd, store("Magic shop"), &book));
        book.pval = magic_idx as i32;
        book.spells = vec![magic_spell];
        assert!(store_will_buy(&gd, store("Magic shop"), &book));
        assert!(!store_will_buy(&gd, store("Temple"), &book));
        // Plain spellbooks go to the Magic shop only.
        let plain_book = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_BOOK && o.sval != 255 && o.sval != 0)
            .expect("a plain spellbook");
        let plain = crate::item::Item::base(&gd, plain_book);
        assert!(store_will_buy(&gd, store("Magic shop"), &plain));
        assert!(!store_will_buy(&gd, store("Temple"), &plain));
        // Blessed weapons count only through the *known* flags (is_blessed,
        // store.cc:614).
        let sword = gd.object_by_name("Long Sword").unwrap();
        let mut blade = crate::item::Item::base(&gd, sword);
        blade.flags.push("BLESSED".to_string());
        blade.identified = false;
        assert!(!store_will_buy(&gd, store("Temple"), &blade));
        blade.identified = true;
        assert!(store_will_buy(&gd, store("Temple"), &blade));
        // The Mathom-house is a museum by flag, so it takes donations.
        let museum = gd
            .stores
            .iter()
            .find(|s| s.flags.iter().any(|f| f == "MUSEUM"))
            .unwrap();
        assert!(store_will_buy(&gd, museum, &blade));
    }

    #[test]
    fn store_carry_sorts_and_discards_worthless_items() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                let store_id = ctx
                    .gd
                    .stores
                    .iter()
                    .find(|s| s.name == "General Store")
                    .unwrap()
                    .id;
                let key = crate::town::skey(1, store_id);
                ctx.stocks.stocks.insert(key, Vec::new());
                let sword = crate::item::Item::base(
                    &ctx.gd,
                    ctx.gd.object_by_name("Long Sword").unwrap(),
                );
                let food = crate::item::Item::base(
                    &ctx.gd,
                    ctx.gd.object_by_name("Ration of Food").unwrap(),
                );
                let spike = crate::item::Item::base(
                    &ctx.gd,
                    ctx.gd.object_by_name("Iron Spike").unwrap(),
                );
                let mut cursed = crate::item::Item::base(
                    &ctx.gd,
                    ctx.gd.object_by_name("Ration of Food").unwrap(),
                );
                cursed.cursed = true;
                for it in [food.clone(), sword.clone(), spike.clone(), cursed.clone(), food] {
                    store_carry(&mut ctx, 1, store_id, it);
                }
                let stock = &ctx.stocks.stocks[&key];
                // The cursed (value 0) item vanished; the rest sorted by
                // decreasing tval (store.cc:976-1010).
                assert!(stock.iter().all(|it| !it.cursed));
                let tvals: Vec<i32> = stock
                    .iter()
                    .map(|it| ctx.gd.objects[it.def].tval)
                    .collect();
                assert!(tvals.windows(2).all(|w| w[0] >= w[1]), "{tvals:?}");
                // The two identical food stacks merged (store_carry).
                let foods = stock
                    .iter()
                    .filter(|it| it.def == ctx.gd.object_by_name("Ration of Food").unwrap())
                    .count();
                assert_eq!(foods, 1);
            })
            .unwrap();
    }

    #[test]
    fn confirm_haggle_marks_found_clears_sale_and_splits_wands() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                let store_id = ctx
                    .gd
                    .stores
                    .iter()
                    .find(|s| s.name == "Magic shop")
                    .unwrap()
                    .id;
                let key = crate::town::skey(1, store_id);
                let wand_def = ctx
                    .gd
                    .objects
                    .iter()
                    .position(|o| o.tval == crate::data::TV_WAND)
                    .unwrap();
                let mut wand = crate::item::Item::base(&ctx.gd, wand_def);
                wand.charges = 10;
                wand.count = 2;
                wand.inscription = "on sale".to_string();
                ctx.stocks.stocks.insert(key, vec![wand]);
                ctx.ps.gold = 100_000;
                // Buy one of the two wands for 100 au.
                confirm_haggle(&mut ctx, store_id, 1, 0, false, 1, 100);
                let bought = ctx.inv.pack.last().expect("bought").clone();
                assert_eq!(bought.found, crate::item::OBJ_FOUND_STORE);
                assert_eq!(bought.found_aux1, store_id as i32);
                assert!(bought.inscription.is_empty(), "on-sale tag cleared");
                assert_eq!(bought.count, 1);
                assert_eq!(bought.charges, 5, "half the charges came along");
                let left = &ctx.stocks.stocks[&key][0];
                assert_eq!(left.count, 1);
                assert_eq!(left.charges, 5, "the shelf keeps the rest");
                // Buying the last one empties the store: four candidate
                // owners means no retirement, new stock is brought out.
                ctx.log.lines.clear();
                confirm_haggle(&mut ctx, store_id, 1, 0, false, 1, 100);
                assert!(
                    ctx.log
                        .lines
                        .iter()
                        .any(|l| l == "The shopkeeper brings out some new stock."),
                    "{:?}",
                    ctx.log.lines
                );
                assert!(
                    !ctx.stocks.stocks[&key].is_empty(),
                    "the shop refilled after the buyout"
                );
            })
            .unwrap();
    }

    #[test]
    fn fix_item_state_machine_matches_bldg_cc() {
        let gd = crate::data::load_game_data();
        let sword = gd.object_by_name("Long Sword").unwrap();
        let mut it = crate::item::Item::base(&gd, sword);
        it.to_h = -3;
        let (s, paid) = fix_item_apply(&mut it, 10, false, false);
        assert_eq!(s, "beyond repair, buy a new one");
        assert!(!paid && it.to_h == -3);
        it.to_h = 0;
        it.to_d = 0;
        let (s, paid) = fix_item_apply(&mut it, 2, false, false);
        assert_eq!(s, "sharpened -> (1,1)");
        assert!(paid && it.to_h == 1 && it.to_d == 1);
        let (s, paid) = fix_item_apply(&mut it, 1, false, false);
        assert_eq!(s, "in fine condition");
        assert!(!paid);
        // An unidentified artifact is left alone; an identified one is
        // beyond the smith's skills (bldg.cc:1006-1010).
        let (s, paid) = fix_item_apply(&mut it, 10, false, true);
        assert_eq!(s, "in fine condition");
        assert!(!paid);
        it.identified = true;
        let (s, paid) = fix_item_apply(&mut it, 10, false, true);
        assert_eq!(s, "beyond our skills!");
        assert!(!paid);
        // Armour uses to_a and the <= -3 refusal.
        let robe = gd.object_by_name("Robe").unwrap();
        let mut ar = crate::item::Item::base(&gd, robe);
        ar.to_a = -3;
        let (s, paid) = fix_item_apply(&mut ar, 10, true, false);
        assert_eq!(s, "beyond repair, buy a new one");
        assert!(!paid);
        ar.to_a = 0;
        let (s, paid) = fix_item_apply(&mut ar, 10, true, false);
        assert_eq!(s, "polished -> (1)");
        assert!(paid);
    }

    #[test]
    fn brand_bolts_applies_the_flame_ego_and_enchant() {
        use bevy::ecs::system::RunSystemOnce;
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                let bolt = ctx
                    .gd
                    .objects
                    .iter()
                    .position(|o| o.tval == crate::data::TV_BOLT)
                    .unwrap();
                let mut bolts = crate::item::Item::base(&ctx.gd, bolt);
                bolts.count = 5;
                ctx.inv.pack.push(bolts);
                // The 75% skip roll needs a lucky seed; loop until it hits.
                let mut done = false;
                for seed in 0..200u64 {
                    let mut rng = StdRng::seed_from_u64(seed);
                    let before = ctx.log.lines.len();
                    brand_bolts(&mut ctx, &mut rng);
                    let fresh: Vec<&String> = ctx.log.lines.iter().skip(before).collect();
                    if fresh
                        .iter()
                        .any(|l| l.as_str() == "Your bolts are covered in a fiery aura!")
                    {
                        done = true;
                        break;
                    }
                }
                assert!(done, "75% roll never passed in 200 seeds");
                let it = &ctx.inv.pack[0];
                assert_eq!(it.ego, crate::base_defs::EGO_FLAME as u32);
                assert!(
                    it.to_h >= 4 && it.to_d >= 4,
                    "enchant(4..6) applied: {} {}",
                    it.to_h,
                    it.to_d
                );
                // A second run on the now-ego item fails (it is skipped).
                let mut rng = StdRng::seed_from_u64(1);
                brand_bolts(&mut ctx, &mut rng);
                assert_eq!(
                    ctx.log.lines.iter().last().unwrap(),
                    "The fiery enchantment failed."
                );
            })
            .unwrap();
    }

    #[test]
    fn rod_of_light_aims_the_lite_line() {
        use bevy::ecs::system::RunSystemOnce;
        // The rod's old-style device roll can fail; retry different RNG
        // streams until the zap goes through.
        let mut world = spells3_world(10, 50, &[]);
        // spells3_world pins every skill, including Antimagic, which would
        // otherwise disrupt the zap (cmd6.cc do_cmd_zap_rod).
        world
            .resource_mut::<crate::game::PlayerState>()
            .skills
            .insert(crate::skill::SK_ANTIMAGIC, 0);
        let (rod_main, tip) = {
            let gd = world.resource::<crate::data::GameData>();
            (
                gd.objects
                    .iter()
                    .position(|o| o.tval == crate::data::TV_ROD_MAIN)
                    .expect("a rod main kind"),
                gd.object_by_tval_sval(
                    crate::data::TV_ROD,
                    crate::base_defs::SV_ROD_LITE as i32,
                )
                .expect("rod of light tip"),
            )
        };
        let mut aimed = false;
        for seed in 0..100u64 {
            world
                .run_system_once(move |mut ctx: ModalCtx| {
                    ctx.inv.pack.clear();
                    *ctx.modal = Modal::None;
                    let tip_sval = ctx.gd.objects[tip].sval;
                    let mut rod = crate::item::Item::base(&ctx.gd, rod_main);
                    rod.pval = tip_sval;
                    rod.pval2 = 100;
                    rod.timeout = 100;
                    ctx.inv.pack.push(rod);
                    crate::rng::set_quick_rng(seed);
                    use_device(&mut ctx, 0, rod_main, crate::data::TV_ROD_MAIN);
                })
                .unwrap();
            if matches!(world.resource::<Modal>(), Modal::Target(_)) {
                aimed = true;
                break;
            }
        }
        assert!(aimed, "the rod of light never aimed");
        match world.resource::<Modal>() {
            Modal::Target(p) => {
                assert_eq!(p.kind, "lite_line");
                assert_eq!(p.device, Some(0));
            }
            _ => panic!("expected a lite-line target"),
        }
        // Firing it prints the original message and lights the beam.
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                let p = PendingTarget {
                    name: "Light".to_string(),
                    kind: "lite_line".to_string(),
                    arg: String::new(),
                    device: None,
                };
                fire_targeted(&mut ctx, &p, 1, 0);
            })
            .unwrap();
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l == "A line of blue shimmering light appears."));
    }

    #[test]
    fn gamble_enter_rolls_and_escape_leaves() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(5, 0, &[]);
        world.resource_mut::<PlayerState>().gold = 10_000;
        *world.resource_mut::<Modal>() = Modal::Gamble {
            game: 16,
            bet: 10,
            maxbet: 1000,
            result: String::new(),
            point: 0,
            start_gold: 10_000,
        };
        world
            .resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>()
            .press(bevy::prelude::KeyCode::Enter);
        world.run_system_once(modal_input).unwrap();
        match world.resource::<Modal>() {
            Modal::Gamble { result, .. } => {
                assert!(!result.is_empty(), "Enter must roll the dice");
            }
            _ => panic!("expected the Gamble modal to stay open"),
        }
        // Escape leaves the table with the winner/loser line.
        let mut keys = world.resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>();
        keys.reset_all();
        keys.press(bevy::prelude::KeyCode::Escape);
        world.run_system_once(modal_input).unwrap();
        assert!(matches!(*world.resource::<Modal>(), Modal::None));
    }

    #[test]
    fn generic_inns_gate_rest_and_food_like_inn_comm() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(5, 0, &[]);
        let inn = {
            let gd = world.resource::<crate::data::GameData>();
            gd.stores.iter().find(|s| s.name == "Inn").unwrap().id
        };
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.gold = 1000;
            // Daytime: a mortal cannot rest.
            ps.turn = crate::game::TURNS_PER_DAY;
        }
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                generic_building_action(&mut ctx, inn, 2); // ba 5 = rest
            })
            .unwrap();
        {
            let log = world.resource::<MessageLog>();
            assert!(log
                .lines
                .iter()
                .any(|l| l == "The rooms are available only at night."));
        }
        assert_eq!(world.resource::<PlayerState>().gold, 1000, "not charged");
        // Night: rest succeeds for the normal cost (20 au).
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.turn = crate::game::TURNS_PER_DAY / 2;
            ps.hp = 1;
            ps.poison = 0;
            ps.cut = 0;
        }
        world.resource_mut::<MessageLog>().lines.clear();
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                generic_building_action(&mut ctx, inn, 2);
            })
            .unwrap();
        {
            let ps = world.resource::<PlayerState>();
            assert_eq!(ps.hp, ps.max_hp);
            assert_eq!(ps.gold, 980);
            assert!(crate::game::is_daytime(ps.turn));
        }
        // Food (ba 6): normal cost 2 au, sets food to PY_FOOD_MAX - 1, and
        // a vampire is refused food but still pays (inn_comm returns true).
        world.resource_mut::<MessageLog>().lines.clear();
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                generic_building_action(&mut ctx, inn, 3);
            })
            .unwrap();
        {
            let ps = world.resource::<PlayerState>();
            assert_eq!(ps.food, crate::game::FOOD_MAX - 1);
            assert_eq!(ps.gold, 978);
        }
        // Poisoned travellers are sent to a healer without charge.
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.poison = 3;
            ps.turn = crate::game::TURNS_PER_DAY / 2;
        }
        world.resource_mut::<MessageLog>().lines.clear();
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                generic_building_action(&mut ctx, inn, 2);
            })
            .unwrap();
        {
            let ps = world.resource::<PlayerState>();
            assert_eq!(ps.gold, 978, "a healer refusal is not charged");
            let log = world.resource::<MessageLog>();
            assert!(log
                .lines
                .iter()
                .any(|l| l == "You need a healer, not a room."));
        }
    }

    #[test]
    fn artifact_name_keeps_default_when_blank() {
        // randart.cc:343-362: empty input keeps create_artifact's
        // "of '<player>'"; a typed name becomes "called '<name>'".
        assert_eq!(artifact_name_from(""), None);
        assert_eq!(artifact_name_from("   "), None);
        assert_eq!(
            artifact_name_from("Sting"),
            Some("called 'Sting'".to_string())
        );
        assert_eq!(
            artifact_name_from("  Sting  "),
            Some("called 'Sting'".to_string())
        );
    }

    #[test]
    fn wield_slot_checks_current_body_parts() {
        use crate::birth::make_player;
        let gd = load_game_data();
        let warrior = gd.classes.iter().position(|c| c.name == "Warrior").unwrap();
        let human = gd.races.iter().position(|r| r.name == "Human").unwrap();
        let deathmold = gd.races.iter().position(|r| r.name == "DeathMold").unwrap();
        let helm = gd.objects.iter().position(|o| o.tval == data::TV_HELM).unwrap();
        let boots = gd.objects.iter().position(|o| o.tval == data::TV_BOOTS).unwrap();
        let ring = gd.objects.iter().position(|o| o.tval == data::TV_RING).unwrap();
        // A normal body has head, feet and fingers.
        let ps = make_player(&gd, "T".into(), human, warrior);
        assert_eq!(
            wield_slot_for(&gd, &ps, &gd.objects[helm]),
            Some(data::SLOT_HEAD)
        );
        assert_eq!(
            wield_slot_for(&gd, &ps, &gd.objects[boots]),
            Some(data::SLOT_FEET)
        );
        assert_eq!(
            wield_slot_for(&gd, &ps, &gd.objects[ring]),
            Some(data::SLOT_RING1)
        );
        // DeathMold's R:E:1:1:1:4:0:0 gives no head and no feet
        // (xtra1.cc calc_body), so C++ get_slot returns -1 and the
        // port's wield_apply refuses ("no body part").
        let dm = make_player(&gd, "M".into(), deathmold, warrior);
        assert!(wield_slot_for(&gd, &dm, &gd.objects[helm]).is_none());
        assert!(wield_slot_for(&gd, &dm, &gd.objects[boots]).is_none());
        assert_eq!(
            wield_slot_for(&gd, &dm, &gd.objects[ring]),
            Some(data::SLOT_RING1)
        );
    }

