    /// A minimal World wired for `ModalCtx`: every resource the spell
    /// effect systems read, the player at (10,10), an optional list of
    /// monsters and every skill pinned so `school_scale(max) == max`.
    fn spells3_world(level: i32, skill: i32, monsters: &[(usize, i32, i32)]) -> World {
        crate::rng::set_quick_rng(0x5EED_5EED);
        let gd = load_game_data();
        let race = gd.races.iter().position(|r| r.name == "Human").unwrap_or(0);
        let class = gd.classes.iter().position(|c| c.name == "Mage").unwrap_or(0);
        let mut ps = crate::birth::make_player(&gd, "S3".into(), race, class);
        ps.level = level.max(1) as u32;
        ps.hp = ps.max_hp;
        ps.max_mana = ps.max_mana.max(1000);
        ps.mana = ps.max_mana;
        ps.skills.clear();
        for id in 0..200u32 {
            ps.skills.insert(id, skill * crate::skill::SKILL_STEP);
        }
        let mut world = World::new();
        world.insert_resource(gd);
        world.insert_resource(ps);
        world.insert_resource(crate::render::TileAssets {
            font: Default::default(),
            bg_image: Default::default(),
            bg_layout: Default::default(),
            fg_image: Default::default(),
            fg_layout: Default::default(),
        });
        world.insert_resource(crate::item::Inventory::default());
        world.insert_resource(crate::map::blank_pub(crate::map::T_FLOOR));
        world.insert_resource(MessageLog::default());
        world.insert_resource(crate::game::TurnState::default());
        world.insert_resource(crate::game::PlotQuest::default());
        world.insert_resource(crate::town::ShopStocks::default());
        world.insert_resource(crate::item::CreatedArtifacts::default());
        world.insert_resource(crate::scores::HighScores::default());
        world.insert_resource(NextState::<crate::AppState>::default());
        world.insert_resource(TargetLock::default());
        world.insert_resource(crate::input::MoveRepeat::default());
        world.insert_resource(crate::options::Options::default());
        world.insert_resource(ModalInputConsumed::default());
        world.insert_resource(Modal::default());
        world.insert_resource(bevy::prelude::ButtonInput::<bevy::prelude::KeyCode>::default());
        world.spawn((GridPos { x: 10, y: 10 }, crate::game::Player));
        for &(def, x, y) in monsters {
            world.spawn((test_monster(def, x, y), GridPos { x, y }));
        }
        world
    }

    /// Remaining hp of the single test monster (0 when it was killed and
    /// despawned by the damage routines).
    fn sole_hp(world: &mut World) -> i32 {
        let mut q = world.query::<&crate::game::Monster>();
        q.iter(world).next().map(|m| m.hp).unwrap_or(0)
    }

    fn cast_untargeted(world: &mut World, name: &str) {
        use bevy::ecs::system::RunSystemOnce;
        let name = name.to_string();
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                if let Some(sp) = ctx.gd.spell_by_name(&name).cloned() {
                    apply_effect(&mut ctx, &sp, None);
                }
            })
            .unwrap();
    }

    fn cast_targeted(world: &mut World, name: &str, dx: i32, dy: i32) {
        use bevy::ecs::system::RunSystemOnce;
        let name = name.to_string();
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                if let Some(sp) = ctx.gd.spell_by_name(&name).cloned() {
                    let p = PendingTarget {
                        name: sp.name.clone(),
                        kind: sp.kind.clone(),
                        arg: sp.arg.clone(),
                        device: None,
                    };
                    fire_targeted(&mut ctx, &p, dx, dy);
                }
            })
            .unwrap();
    }

    #[test]
    fn spells3_air_spells_follow_the_original_effects() {
        // Wings of Winds (spells3.cc:240): at school level 16+ flight,
        // otherwise feather fall; duration d10 + 5 + scale(25).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Wings of Winds");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.tim_fly > 0 && ps.tim_ffall == 0, "flight at level 50");
        assert!((31..=40).contains(&ps.tim_fly), "dur {}", ps.tim_fly);
        // Below skill 16 the same spell only grants feather fall.
        let mut world = spells3_world(50, 10, &[]);
        cast_untargeted(&mut world, "Wings of Winds");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.tim_ffall > 0 && ps.tim_fly == 0, "feather fall at 10");

        // Invisibility (spells3.cc:265): 15 + scale(50) + d20 turns,
        // power 20 + scale(50).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Invisibility");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((66..=85).contains(&ps.invis_turns), "{}", ps.invis_turns);
        assert_eq!(ps.invis_power, 70);

        // Poison Blood (spells3.cc:283): oppose poison for
        // 25 + scale(25) + d30; at level 15+ a poison aura too.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Poison Blood");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((51..=80).contains(&ps.oppose_pois), "{}", ps.oppose_pois);
        assert!(ps.tim_poison >= 51, "poison aura at level 15+");

        // Thunderstorm (spells3.cc:310): tim_thunder = d10 + 10 +
        // scale(25) with 5+scale(10)/10+scale(25) bolt dice.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Thunderstorm");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((36..=45).contains(&ps.tim_thunder), "{}", ps.tim_thunder);

        // Sterilize (spells3.cc:329): no breeding for 50 + scale(70).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Sterilize");
        let ps = world.resource::<crate::game::PlayerState>();
        assert_eq!(ps.no_breeders, 120);

        // Probability Travel (spells3.cc:488): scale(60) + d20.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Probability Travel");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((61..=80).contains(&ps.prob_travel), "{}", ps.prob_travel);
    }

    #[test]
    fn spells3_noxious_cloud_matches_the_original() {
        // air_noxious_cloud (spells3.cc:210): GF_UNBREATH from skill 30,
        // damage 7+scale(150), duration 5+scale(40), radius 3.
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Noxious Cloud", 1, 0);
        let map = world.resource::<crate::map::Map>();
        let cloud = map.clouds.last().expect("cloud");
        assert_eq!(cloud.radius, 3);
        assert_eq!(cloud.damage, 157);
        assert_eq!(cloud.turns, 45);
        assert_eq!(cloud.gf, "UNBREATH");
        // Below skill 30 it is an ordinary poison cloud.
        let mut world = spells3_world(50, 10, &[]);
        cast_targeted(&mut world, "Noxious Cloud", 1, 0);
        let map = world.resource::<crate::map::Map>();
        assert_eq!(map.clouds.last().expect("cloud").gf, "POIS");
    }

    #[test]
    fn spells3_conveyance_spells_follow_the_original_effects() {
        // Phase Door (convey_blink, spells3.cc:342): teleport
        // 10 + get_level_s(BLINK, 8); from effective level 30 a void
        // jumpgate is left behind.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Phase Door");
        assert!(world
            .resource::<crate::game::PlayerState>()
            .last_teleport
            .is_some());
        assert!(
            !world.resource::<crate::map::Map>().between.is_empty(),
            "jumpgate at level 30+"
        );

        // Teleport (convey_teleport, spells3.cc:367):
        // teleport_player(100 + get_level_s(TELEPORT, 100)).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Teleport");
        assert!(world
            .resource::<crate::game::PlayerState>()
            .last_teleport
            .is_some());

        // Teleport Away (convey_teleport_away, spells3.cc:381): from
        // display level 20 every visible monster is teleported away.
        let mut world = spells3_world(50, 50, &[(1, 14, 10)]);
        world.resource_mut::<crate::map::Map>().visible.fill(true);
        cast_targeted(&mut world, "Teleport Away", 1, 0);
        let mut q = world.query::<&GridPos>();
        let positions: Vec<(i32, i32)> = q.iter(&world).map(|p| (p.x, p.y)).collect();
        assert!(positions.contains(&(10, 10)));
        assert!(!positions.contains(&(14, 10)), "monster teleported away");
    }

    #[test]
    fn spells3_recall_spell_swaps_fetches_and_recalls() {
        let gd = load_game_data();
        // Self (convey_recall, spells3.cc:430): recall_player with
        // d = max(0, 21 - ls(15)), f = max(1, 15 - ls(10)).
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Word of Recall", 1, 0);
        assert!(
            world.resource::<crate::game::PlayerState>().word_recall > 0,
            "self recall starts the countdown"
        );

        // A monster on the ray: swap_position.
        let def = gd.monsters.iter().position(|m| !m.unique).unwrap();
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        cast_targeted(&mut world, "Word of Recall", 1, 0);
        let mut pq = world.query_filtered::<&GridPos, With<crate::game::Player>>();
        let pp = *pq.single(&world).unwrap();
        assert_eq!((pp.x, pp.y), (14, 10), "player swapped forward");
        let mut mq = world.query_filtered::<&GridPos, Without<crate::game::Player>>();
        let mp = *mq.single(&world).unwrap();
        assert_eq!((mp.x, mp.y), (10, 10), "monster swapped back");

        // A floor object on the ray: fetch(5, 10 + ls(150), ...).
        let pot = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_POTION)
            .unwrap();
        let mut world = spells3_world(50, 50, &[]);
        let item = {
            let wgd = world.resource::<crate::data::GameData>();
            crate::item::Item::base(wgd, pot)
        };
        world
            .spawn((crate::item::FloorItem { stack: vec![item] }, GridPos { x: 12, y: 10 }));
        cast_targeted(&mut world, "Word of Recall", 1, 0);
        let mut q = world.query::<(&GridPos, &crate::item::FloorItem)>();
        let moved: Vec<(i32, i32)> = q
            .iter(&world)
            .map(|(p, _)| (p.x, p.y))
            .filter(|c| *c != (12, 10))
            .collect();
        assert!(
            moved.iter().any(|c| *c == (10, 10)) || moved.is_empty(),
            "object fetched to the player or packed: {moved:?}"
        );
        let mut q2 = world.query::<(&GridPos, &crate::item::FloorItem)>();
        assert!(
            !q2.iter(&world).any(|(p, _)| (p.x, p.y) == (12, 10)),
            "original stack emptied"
        );
    }

    #[test]
    fn spells3_demonology_spells_follow_the_original_effects() {
        let gd = load_game_data();
        // Demon Blade (spells3.cc:501): d20 + scale(80) turns, damage
        // 4 + scale(40), hell fire from 30, radius 1 from 45.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Demon Blade");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((81..=100).contains(&ps.tim_project), "{}", ps.tim_project);
        assert_eq!(ps.tim_project_gf, "HELL_FIRE");
        assert_eq!(ps.tim_project_dam, 44);
        assert_eq!(ps.tim_project_rad, 1);

        // Doom Shield (spells3.cc:624): d10 + 20 + scale(100) turns,
        // AC -300 + scale(100) and a 1+14 / 10+15 riposte.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Doom Shield");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((121..=130).contains(&ps.shield), "{}", ps.shield);
        assert_eq!(ps.shield_power, -200);
        assert_eq!(ps.shield_counter, (15, 25));

        // Demon Cloak (spells3.cc:708): d5 + 5 + scale(15).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Demon Cloak");
        assert!((21..=25).contains(
            &world.resource::<crate::game::PlayerState>().tim_reflect
        ));

        // Summon Demon (spells3.cc:721): SUMMON_HI_DEMON at scale(50)
        // >= 35; a friendly demon appears.
        // At skill 50 SUMMON_HI_DEMON has no non-unique glyph-U candidates
        // within the level cap (the original fails with a message too).
        let mut world = spells3_world(50, 50, &[]);
        world.resource_mut::<crate::game::PlayerState>().depth = 30;
        cast_untargeted(&mut world, "Summon Demon");
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l.contains("Something blocks your summoning")));
        // Below skill 35 the ordinary demon pool answers.
        let mut world = spells3_world(50, 20, &[]);
        world.resource_mut::<crate::game::PlayerState>().depth = 30;
        cast_untargeted(&mut world, "Summon Demon");
        let mut q = world.query::<&crate::game::Monster>();
        assert_eq!(q.iter(&world).count(), 1, "a demon joins");

        // Demon Field (spells3.cc:598): a nexus cloud, 20+scale(70) dam,
        // 30+scale(100) turns, radius 7.
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Demon Field", 1, 0);
        let map = world.resource::<crate::map::Map>();
        let cloud = map.clouds.last().expect("cloud");
        assert_eq!(cloud.gf, "NEXUS");
        assert_eq!(cloud.damage, 90);
        assert_eq!(cloud.turns, 130);
        assert_eq!(cloud.radius, 7);

        // Demon Madness (spells3.cc:534): two balls of chaos, confusion
        // or charm, 20+scale(200) at radius 1+scale(4).
        let def = gd
            .monsters
            .iter()
            .position(|m| !m.unique && !m.has("NO_CONF") && m.depth <= 5)
            .unwrap();
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        world.resource_mut::<crate::map::Map>().visible.fill(true);
        cast_targeted(&mut world, "Demon Madness", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        let m = q.iter(&world).next().unwrap();
        assert!(m.hp < 100 || m.companion, "madness hits or charms");

        // Discharge Minion (spells3.cc:756): the pet is consumed and a
        // gravity burst of hp*(20+scale(60))/100 capped at
        // 100+scale(500) lands on its cell.
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        {
            let mut q = world.query::<&mut crate::game::Monster>();
            let mut m = q.iter_mut(&mut world).next().unwrap();
            m.companion = true;
            m.pet = true;
        }
        cast_targeted(&mut world, "Discharge Minion", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert_eq!(q.iter(&world).count(), 0, "pet discharged");

        // Control Demon (spells3.cc:807): 50+scale(250) power binds a
        // demon but not uniques.
        let demon = gd
            .monsters
            .iter()
            .position(|m| m.has("DEMON") && !m.unique)
            .unwrap();
        let mut world = spells3_world(50, 50, &[(demon, 14, 10)]);
        cast_targeted(&mut world, "Control Demon", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert!(q.iter(&world).next().unwrap().companion, "demon bound");

        // Unholy Word (spells3.cc:644): the pet is consumed to heal
        // (30+L50)% of its hp fraction, 30-scale(25) percent of the
        // time it turns instead.
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        world.resource_mut::<crate::game::PlayerState>().hp = 1;
        {
            let mut q = world.query::<&mut crate::game::Monster>();
            let mut m = q.iter_mut(&mut world).next().unwrap();
            m.companion = true;
        }
        cast_targeted(&mut world, "Unholy Word", 1, 0);
        let pet_gone = {
            let mut q = world.query::<&crate::game::Monster>();
            q.iter(&world).count() == 0
        };
        let hp = world.resource::<crate::game::PlayerState>().hp;
        assert_eq!(hp > 1, pet_gone, "turned (hp {hp}) or consumed");

        // Melkor's Mind Steal (spells3.cc:2047): randint(level) <
        // scale(50) takes control of a non-unique monster.
        let weak = gd.monsters.iter().position(|m| !m.unique && m.depth <= 2).unwrap();
        let mut world = spells3_world(50, 50, &[(weak, 14, 10)]);
        cast_targeted(&mut world, "Mind Steal", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert!(q.iter(&world).next().unwrap().controlled);

        // Corpse Explosion (spells3.cc:2030): corpses within 2+scale(5)
        // become shard balls of 20+scale(70) percent of their hp.
        let corpse = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_CORPSE)
            .unwrap();
        let mut world = spells3_world(50, 50, &[]);
        let mut it = {
            let wgd = world.resource::<crate::data::GameData>();
            crate::item::Item::base(wgd, corpse)
        };
        it.note = def as u32;
        world.spawn((
            crate::item::FloorItem { stack: vec![it] },
            GridPos { x: 12, y: 10 },
        ));
        cast_untargeted(&mut world, "Corpse Explosion");
        let mut q = world.query::<&crate::item::FloorItem>();
        assert_eq!(q.iter(&world).count(), 0, "corpse consumed");
    }

    #[test]
