    #[test]
    fn spells3_earth_and_fire_spells_follow_the_original_effects() {
        // Stone Skin (spells3.cc:904): shield d10 + 10 + scale(100),
        // power 10 + scale(50), riposte 2+scale(5) / 3+scale(5) at 25+.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Stone Skin");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((111..=120).contains(&ps.shield), "{}", ps.shield);
        assert_eq!(ps.shield_power, 60);
        assert_eq!(ps.shield_counter, (7, 8));

        // Dig (spells3.cc:941): wall_to_mud melts a tunnelable wall.
        let mut world = spells3_world(50, 50, &[]);
        world
            .resource_mut::<crate::map::Map>()
            .set_terrain(11, 10, crate::map::T_GRANITE);
        cast_targeted(&mut world, "Dig", 1, 0);
        assert_ne!(
            world.resource::<crate::map::Map>().terrain_at(11, 10),
            crate::map::T_GRANITE
        );

        // Stone Prison (spells3.cc:953): a granite ring at the target
        // (self below school level 10).
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Stone Prison", 1, 0);
        let map = world.resource::<crate::map::Map>();
        let mut walls = 0;
        for dy in -1..=1 {
            for dx in -1..=1 {
                if dx == 0 && dy == 0 {
                    continue;
                }
                if map.terrain_at(30 + dx, 10 + dy) == crate::map::T_GRANITE {
                    walls += 1;
                }
            }
        }
        assert!(walls > 0, "prison walls placed");

        // Strike (spells3.cc:974): 50 + scale(50) force damage, a
        // radius-1 ball from school level 12.
        let def = load_game_data()
            .monsters
            .iter()
            .position(|m| !m.unique && !m.has("RES_FORCE") && !m.has("IM_FORCE"))
            .unwrap();
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        cast_targeted(&mut world, "Strike", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert!(sole_hp(&mut world) < 100, "force hit");

        // Shake (spells3.cc:1008): earthquake(4 + scale(10)) around the
        // target (self below 10).
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Shake", 1, 0);
        assert!(!world.resource::<MessageLog>().lines.is_empty());

        // Globe of Light (spells3.cc:1094): light area, plus a
        // 10+scale(100) radius 5+scale(6) light ball from level 15.
        let lite_def = load_game_data()
            .monsters
            .iter()
            .position(|m| m.has("HURT_LITE") && !m.unique)
            .unwrap();
        let mut world = spells3_world(50, 50, &[(lite_def, 12, 10)]);
        cast_untargeted(&mut world, "Globe of Light");
        let mut q = world.query::<&crate::game::Monster>();
        assert!(sole_hp(&mut world) < 100, "light burned");

        // Fireflash (spells3.cc:1133): 20+scale(500) radius
        // 2+scale(5), holy fire at school level 20.
        let def = load_game_data()
            .monsters
            .iter()
            .position(|m| !m.unique && !m.has("IM_FIRE") && !m.has("RES_FIRE"))
            .unwrap();
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        cast_targeted(&mut world, "Fireflash", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert!(sole_hp(&mut world) < 100, "fireball hit");

        // Fiery Shield (spells3.cc:1164): shield d20 + 10 + scale(70),
        // AC 10, flame dice 5+scale(10) / 5+scale(7), greater fire at 8.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Fiery Shield");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((81..=100).contains(&ps.shield), "{}", ps.shield);
        assert_eq!(ps.shield_power, 10);
        assert!(ps.shield_fire.0 > 0 && ps.shield_fire.1 > 0);
        assert!(ps.shield_great_fire);

        // Firewall (spells3.cc:1190): a line of hell-fire clouds,
        // 40+scale(150) damage for 10+scale(14) turns.
        let mut world = spells3_world(50, 50, &[]);
        cast_targeted(&mut world, "Firewall", 1, 0);
        let map = world.resource::<crate::map::Map>();
        let cloud = map.clouds.last().expect("cloud");
        assert_eq!(cloud.gf, "HELL_FIRE");
        assert_eq!(cloud.damage, 190);
        assert_eq!(cloud.turns, 24);
    }

    #[test]
    fn spells3_fire_golem_follows_the_original() {
        use bevy::ecs::system::RunSystemOnce;
        // fire_golem (spells3.cc:1229): burn a light source, place the
        // golem at a find_position spot (6 cells) and level it to
        // 7 + scale(70), then control it.
        let gd = load_game_data();
        let torch = gd.object_by_tval_sval(crate::data::TV_LITE, 1).unwrap();
        let mut world = spells3_world(50, 50, &[]);
        let it = {
            let wgd = world.resource::<crate::data::GameData>();
            crate::item::Item::base(wgd, torch)
        };
        world.resource_mut::<crate::item::Inventory>().pack.push(it);
        cast_untargeted(&mut world, "Fire Golem");
        // The spell offers its own light-source selection window.
        assert!(matches!(
            *world.resource::<Modal>(),
            Modal::FireGolem { .. }
        ));
        // Choosing the torch burns it and spawns the controlled golem.
        world
            .run_system_once(move |mut ctx: ModalCtx| {
                summon_fire_golem(&mut ctx, FireGolemLight::Pack(0));
            })
            .unwrap();
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.control.is_some(), "golem controlled");
        assert!(world.resource::<crate::item::Inventory>().pack.is_empty());
        let mut q = world.query::<&crate::game::Monster>();
        assert_eq!(q.iter(&world).count(), 1, "golem placed");
    }

    #[test]
    fn spells3_eru_spells_follow_the_original_effects() {
        // See the Music (spells3.cc:1034): tim_invis for
        // 10 + d20 + scale(100), map at 10+, cure blind at 20+,
        // clairvoyance at 30+.
        let mut world = spells3_world(50, 50, &[]);
        world.resource_mut::<crate::game::PlayerState>().blind = 30;
        cast_untargeted(&mut world, "See the Music");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.tim_invis >= 111, "{}", ps.tim_invis);
        assert_eq!(ps.blind, 0, "blindness cured at 20+");
        assert!(world
            .resource::<crate::map::Map>()
            .explored
            .iter()
            .all(|e| *e));

        // Listen to the Music (spells3.cc:1062): identify one item,
        // the pack at 14+, everything at 30+.
        let mut world = spells3_world(50, 50, &[]);
        {
            let it = {
                let gd = world.resource::<crate::data::GameData>();
                let def = gd
                    .objects
                    .iter()
                    .position(|o| o.tval == crate::data::TV_POTION)
                    .unwrap();
                let mut it = crate::item::Item::base(&gd, def);
                it.identified = false;
                it
            };
            world.resource_mut::<crate::item::Inventory>().pack.push(it);
        }
        cast_untargeted(&mut world, "Listen to the Music");
        assert!(world
            .resource::<crate::item::Inventory>()
            .pack
            .iter()
            .all(|it| it.identified));

        // Lay of Protection (spells3.cc:1081): glyph of warding balls
        // of radius 1 + get_level(ERU_PROT, 2).
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Lay of Protection");
        assert_eq!(
            world.resource::<crate::map::Map>().terrain_at(10, 10),
            3,
            "glyph at the player"
        );
    }

