    #[test]
    fn spells3_mana_and_meta_spells_follow_the_original_effects() {
        let gd = load_game_data();
        // Manathrust (spells3.cc:1690): 3+scale(50) d 1+scale(20) mana
        // bolt.
        let def = gd.monsters.iter().position(|m| !m.unique).unwrap();
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        cast_targeted(&mut world, "Manathrust", 1, 0);
        let mut q = world.query::<&crate::game::Monster>();
        assert!(sole_hp(&mut world) < 100, "mana bolt hit");

        // Remove Curses (spells3.cc:1715): *remove curses* at level 20+.
        let mut world = spells3_world(50, 50, &[]);
        {
            let it = {
                let gd = world.resource::<crate::data::GameData>();
                let def = gd
                    .objects
                    .iter()
                    .position(|o| o.tval == crate::data::TV_SWORD)
                    .unwrap();
                let mut it = crate::item::Item::base(&gd, def);
                it.cursed = true;
                it
            };
            world.resource_mut::<crate::item::Inventory>().equip[crate::data::SLOT_WEAPON] = Some(it);
        }
        cast_untargeted(&mut world, "Remove Curses");
        assert!(!world
            .resource::<crate::item::Inventory>()
            .equip[crate::data::SLOT_WEAPON]
            .as_ref()
            .unwrap()
            .cursed);

        // Elemental Shield (spells3.cc:1729): d10 + 15 + scale(50)
        // resistance to the four elements.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Elemental Shield");
        let ps = world.resource::<crate::game::PlayerState>();
        for v in [ps.oppose_fire, ps.oppose_cold, ps.oppose_elec, ps.oppose_acid] {
            assert!((66..=75).contains(&v), "{v}");
        }

        // Disruption Shield (spells3.cc:1767): d5 + 3 + scale(10)
        // invulnerability at level 5+.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Disruption Shield");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!((14..=18).contains(&ps.invuln), "{}", ps.invuln);

        // Recharge (spells3.cc:2095): 60 + scale(140) power.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Recharge");
        match *world.resource::<Modal>() {
            Modal::Recharge { power, .. } => assert!(power >= 60, "{power}"),
            _ => panic!("expected Recharge"),
        }

        // Spellbinder (spells3.cc:2118): opens the trigger window.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Spellbinder");
        assert!(matches!(
            *world.resource::<Modal>(),
            Modal::SpellbinderTrigger
        ));

        // Disperse Magic (spells3.cc:2222): strips every magical effect.
        let mut world = spells3_world(50, 50, &[]);
        {
            let mut ps = world.resource_mut::<crate::game::PlayerState>();
            ps.hero = 50;
            ps.shero = 50;
            ps.blessed = 50;
            ps.shield = 50;
            ps.fear = 50;
            ps.invuln = 50;
        }
        cast_untargeted(&mut world, "Disperse Magic");
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.hero == 0 && ps.shero == 0 && ps.blessed == 0);
        assert!(ps.shield == 0 && ps.fear == 0 && ps.invuln == 0);

        // Tracker (spells3.cc:2255): return to the last teleport.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Tracker");
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l.contains("teleportation")));
        world.resource_mut::<crate::game::PlayerState>().last_teleport = Some((5, 5));
        cast_untargeted(&mut world, "Tracker");
        let mut q = world.query_filtered::<&GridPos, With<crate::game::Player>>();
        let p = *q.single(&world).unwrap();
        assert_eq!((p.x, p.y), (5, 5));

        // Inertia Control (spells3.cc:2283): opens the controlled-spell
        // selection window.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Inertia Control");
        assert!(matches!(*world.resource::<Modal>(), Modal::Inertia { .. }));
    }

