        // Confuse (spells3.cc:2413): GF_OLD_CONF ball from level 15,
        // every visible monster from 35.
        let mut world = spells3_world(50, 50, &[(def, 14, 10)]);
        world.resource_mut::<crate::map::Map>().visible.fill(true);
        cast_targeted(&mut world, "Confuse", 1, 0);
