        assert!(ps.tim_project_dam > 4);
        assert_eq!(ps.tim_project_rad, 1);

        // Enchant Weapon (spells3.cc:3808): to_h/to_d/pval rolls.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Enchant Weapon");
        match *world.resource::<Modal>() {
            Modal::AuleEnchant { armour, to_h, .. } => {
                assert!(!armour);
                assert!(to_h >= 1);
            }
            _ => panic!("expected AuleEnchant"),
        }

        // Enchant Armour (spells3.cc:3873): to_a/to_h/to_d/pval.
        let mut world = spells3_world(50, 50, &[]);
        cast_untargeted(&mut world, "Enchant Armour");
        match *world.resource::<Modal>() {
            Modal::AuleEnchant { armour, to_a, .. } => {
                assert!(armour);
                assert!(to_a >= 1);
            }
            _ => panic!("expected AuleEnchant"),
        }

        // Child of Aule (spells3.cc:3919): a Dwarven warrior of
