    #[test]
    fn spells1_spellbinder_release_and_companion_immunity() {
        use bevy::ecs::system::RunSystemOnce;
        // spellbinder_trigger (spells1.cc:1202): crossing the hp threshold
        // fires every stored spell for free and clears the binder.
        let mut world = spells3_world(50, 50, &[]);
        {
            let mut ps = world.resource_mut::<crate::game::PlayerState>();
            ps.hp = 10;
            // Give the heal headroom (the fixture's max_hp is the
            // creation roll, not a level-50 recompute).
            ps.max_hp = ps.max_hp.max(100);
            ps.spellbinder = Some(crate::game::SpellBinder {
                trigger: 50,
                spells: vec!["Cure Light Wounds".to_string()],
            });
            ps.spellbinder_pending = true;
        }
        world
            .run_system_once(|mut ctx: ModalCtx| {
                assert!(resolve_pending_casts(&mut ctx));
            })
            .unwrap();
        let ps = world.resource::<crate::game::PlayerState>();
        assert!(ps.hp > 10, "the bound heal fired: hp {}", ps.hp);
        assert!(ps.spellbinder.is_none(), "binder cleared");

        // hurt_monster (spells1.cc:4046): companions never take damage.
        let mut world = spells3_world(50, 50, &[(1, 12, 10)]);
        {
            let mut q = world.query::<&mut crate::game::Monster>();
            for mut m in q.iter_mut(&mut world) {
                m.companion = true;
            }
        }
        world
            .run_system_once(|mut ctx: ModalCtx| {
                let e = ctx.monsters.iter().next().expect("monster").0;
                hurt_monster(&mut ctx, e, 1000, "test", &mut crate::rng::current());
            })
            .unwrap();
        assert_eq!(sole_hp(&mut world), 100, "companion untouched");
    }

