    #[test]
    fn god_compass_distance_and_directions_follow_q_god() {
        // compass (q_god.cc:52): within two grids is "close" (empty), then
        // the eight directions joined with '-'.
        assert_eq!(game::compass(10, 10, 11, 12), "");
        assert_eq!(game::compass(10, 10, 5, 10), "north");
        assert_eq!(game::compass(10, 10, 20, 10), "south");
        assert_eq!(game::compass(10, 10, 10, 20), "east");
        assert_eq!(game::compass(10, 10, 10, 2), "west");
        assert_eq!(game::compass(10, 10, 20, 20), "south-east");
        assert_eq!(game::compass(10, 10, 2, 2), "north-west");
        // approximate_distance (q_god.cc:109): the larger axis decides.
        assert_eq!(game::approximate_distance(0, 0, 7, 7), "not very far");
        assert_eq!(game::approximate_distance(0, 0, 8, 0), "quite some way");
        assert_eq!(game::approximate_distance(0, 0, 25, 0), "a long way");
        assert_eq!(game::approximate_distance(0, 0, 0, 41), "a very long way");
        // make_directions (q_god.cc:233): the ToME waypoints; Melkor uses
        // Angband and Mordor instead of Bree and Minas Anor.
        let gd = load_game_data();
        let mut plot = game::PlotQuest::default();
        let mut ps = crate::birth::make_player(&gd, "T".into(), 0, 0);
        ps.god = 1;
        plot.god_temple = Some((34, 21)); // Bree's cell
        let text = game::god_directions(&plot, &ps);
        assert!(text.contains("very close to Bree"), "{text}");
        assert!(text.contains("Minas Anor"), "{text}");
        ps.god = 4; // Melkor
        plot.god_temple = Some((65, 58));
        let text = game::god_directions(&plot, &ps);
        assert!(text.contains("the Pits of Angband"), "{text}");
        assert!(text.contains("very close to the Land of Mordor"), "{text}");
        plot.god_temple = None;
        assert!(game::god_directions(&plot, &ps).is_empty());
    }

    #[test]
    fn god_quest_level_up_gates_follow_q_god() {
        let gd = load_game_data();
        let mut rng = crate::rng::new_seeded_rng(7);
        let mut log = MessageLog::default();
        // The 21% roll needs at most a few level-ups; a huge experience
        // pool climbs to 50 in one call (q_god.cc quest_god_player_level_hook).
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        ps.god = 1;
        ps.exp = u64::MAX / 4;
        game::check_experience(&mut ps, &mut log, &mut rng);
        assert!(ps.relic_quest, "a god quest was granted");
        // Unlike q_god.cc's cquest_quests_given, the port increments the
        // counter when the relic piece is picked up (input.rs); the cap is
        // still five because an abandoned quest fails permanently.
        assert_eq!(ps.god_quests, 0, "counted at pickup");

        // MAX_NUM_GOD_QUESTS (q_god.cc:133): five relics per ToME game.
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        ps.god = 1;
        ps.god_quests = 5;
        ps.exp = u64::MAX / 4;
        game::check_experience(&mut ps, &mut log, &mut rng);
        assert!(!ps.relic_quest, "no sixth quest");

        // An astral being is refused (q_god.cc:979).
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        ps.god = 1;
        ps.astral = true;
        ps.exp = u64::MAX / 4;
        game::check_experience(&mut ps, &mut log, &mut rng);
        assert!(!ps.relic_quest, "astral refused");

        // Standing in the Lost Temple refuses the quest (q_god.cc:985).
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        ps.god = 1;
        ps.dungeon = game::DUNGEON_GOD;
        ps.depth = 5;
        ps.exp = u64::MAX / 4;
        game::check_experience(&mut ps, &mut log, &mut rng);
        assert!(!ps.relic_quest, "no quest inside the temple");

        // No god: no quests.
        let mut ps = crate::birth::make_player(&gd, "G".into(), 0, 0);
        ps.god = 0;
        ps.exp = u64::MAX / 4;
        game::check_experience(&mut ps, &mut log, &mut rng);
        assert!(!ps.relic_quest, "godless refused");
    }

    #[test]
    fn god_relic_reward_and_piece_objects_follow_q_god() {
        let gd = load_game_data();
        // get_relic_num (q_god.cc:148): one TV_JUNK piece per ToME god with
        // the original svals 7..11 (the Theme gods' 16..19 are exempt).
        for (name, sval) in [
            ("Eru", 7),
            ("Manwe", 8),
            ("Tulkas", 9),
            ("Melkor", 10),
            ("Yavanna", 11),
        ] {
            let def = gd
                .object_by_name(&format!("Piece of the Relic of {name}"))
                .unwrap_or_else(|| panic!("relic of {name}"));
            assert_eq!(gd.objects[def].tval, data::TV_JUNK);
            assert_eq!(gd.objects[def].sval, sval);
        }
        // quest_god_get_hook reward: 5 * Prayer mod, doubled on the last
        // piece (q_god.cc:1056-1066).
        let mut ps = crate::birth::make_player(&gd, "P".into(), 0, 0);
        ps.skills.clear();
        ps.skill_mods.insert(crate::skill::SK_PRAY, 3);
        let mut log = MessageLog::default();
        ps.god_quests = 1;
        game::god_relic_reward(&mut ps, &mut log);
        assert_eq!(ps.skill_value(crate::skill::SK_PRAY), 15);
        assert!(log.lines.iter().any(|l| l.contains("Well done")));
        ps.god_quests = 5;
        game::god_relic_reward(&mut ps, &mut log);
        assert_eq!(ps.skill_value(crate::skill::SK_PRAY), 15 + 30);
        assert!(log.lines.iter().any(|l| l.contains("At last")));
    }

    #[test]
    fn god_temple_placement_follows_q_god() {
        let gd = load_game_data();
        let mut rng = crate::rng::new_seeded_rng(11);
        let mut plot = game::PlotQuest::default();
        let (x, y) = game::place_god_temple(&gd, &mut plot, &mut rng);
        assert_eq!(plot.god_temple, Some((x, y)));
        assert!(x >= 1 && x < gd.world.w - 1 && y >= 1 && y < gd.world.h - 1);
        // Not on an existing entrance nor an impassable edge/water/forest/
        // lava/mountain cell (q_god.cc:329-343).
        assert!(!gd.world.entrances.iter().any(|e| e.x == x && e.y == y));
        let wf = gd.wf(gd.world.feat(x, y, &plot.destroyed_towns));
        assert_eq!(wf.entrance, 0);
        assert!(!matches!(wf.terrain_idx, 0 | 2 | 7 | 9 | 10 | 11));
        // The cell maps to the Lost Temple dungeon (DUNGEON_GOD).
        let wild = game::Wilderness::default();
        assert_eq!(
            wild.dungeon_at(&gd, x, y, &plot),
            Some(game::DUNGEON_GOD)
        );
        // A second call keeps the placed cell.
        let again = game::place_god_temple(&gd, &mut plot, &mut rng);
        assert_eq!(again, (x, y));
        // quest_god_dungeon_setup (q_god.cc:1179): the Lost Temple's
        // mindepth/maxdepth/min_plev live in the static dungeon record the
        // per-god attribute patches used to write (dungeons.ron id 30).
        let temple = gd.dungeon(game::DUNGEON_GOD);
        assert_eq!((temple.mindepth, temple.maxdepth, temple.min_plev), (1, 50, 1));
        assert!(temple.has("NO_RECALL"));
    }

    #[test]
    fn god_relic_generation_follows_q_god() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(1, 0, &[]);
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.god = 1;
            ps.relic_quest = true;
            ps.relic_depth = 0;
            ps.relic_tries = 0;
            ps.dungeon = game::DUNGEON_GOD;
            ps.depth = 5;
        }
        world
            .run_system_once(
                move |mut commands: Commands,
                      gd: Res<GameData>,
                      tiles: Res<TileAssets>,
                      mut map: ResMut<Map>,
                      mut plot: ResMut<game::PlotQuest>,
                      mut ps: ResMut<PlayerState>,
                      mut inv: ResMut<Inventory>,
                      mut created: ResMut<crate::item::CreatedArtifacts>,
                      mut log: ResMut<MessageLog>| {
                    let mut rng = crate::rng::current();
                    game::populate_level(
                        &mut commands,
                        &gd,
                        &tiles,
                        &mut map,
                        &crate::map::VaultSpawns::default(),
                        5,
                        game::DUNGEON_GOD,
                        (30, 15),
                        &mut created.0,
                        &mut inv,
                        &mut plot,
                        &mut ps,
                        &mut rng,
                        &mut log,
                    );
                },
            )
            .unwrap();
        // The Lost Temple always holds the relic (q_god.cc quest_random_gen
        // equivalent: `ps.dungeon == DUNGEON_GOD` forces the level).
        assert_eq!(world.resource::<PlayerState>().relic_depth, 5);
        let mut q = world.query::<&crate::item::FloorItem>();
        let relics: Vec<_> = q
            .iter(&world)
            .filter(|f| f.stack.iter().any(|it| it.inscription == "quest"))
            .collect();
        assert_eq!(relics.len(), 1, "one inscribed relic piece on the level");
        assert!(relics[0]
            .stack
            .iter()
            .any(|it| gd_object_name(&world, it.def).starts_with("Piece of the Relic")));

        // The 5th try forces the relic too (q_god.cc:946
        // cquest_relic_gen_tries == 4), still only inside the god
        // dungeon - the whole hook is gated on DUNGEON_GOD (q_god.cc:936).
        let mut world = spells3_world(1, 0, &[]);
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.god = 2;
            ps.relic_quest = true;
            ps.relic_depth = 0;
            ps.relic_tries = 4;
            ps.dungeon = game::DUNGEON_GOD;
            ps.depth = 7;
        }
        world
            .run_system_once(
                move |mut commands: Commands,
                      gd: Res<GameData>,
                      tiles: Res<TileAssets>,
                      mut map: ResMut<Map>,
                      mut plot: ResMut<game::PlotQuest>,
                      mut ps: ResMut<PlayerState>,
                      mut inv: ResMut<Inventory>,
                      mut created: ResMut<crate::item::CreatedArtifacts>,
                      mut log: ResMut<MessageLog>| {
                    let mut rng = crate::rng::current();
                    game::populate_level(
                        &mut commands,
                        &gd,
                        &tiles,
                        &mut map,
                        &crate::map::VaultSpawns::default(),
                        7,
                        9,
                        (30, 15),
                        &mut created.0,
                        &mut inv,
                        &mut plot,
                        &mut ps,
                        &mut rng,
                        &mut log,
                    );
                },
            )
            .unwrap();
        assert_eq!(world.resource::<PlayerState>().relic_depth, 7);

        // Outside the god dungeon the hook returns before any roll, so
        // even the 5th try generates nothing (q_god.cc:936-941).
        let mut world = spells3_world(1, 0, &[]);
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.god = 2;
            ps.relic_quest = true;
            ps.relic_depth = 0;
            ps.relic_tries = 4;
            ps.dungeon = 9;
            ps.depth = 7;
        }
        world
            .run_system_once(
                move |mut commands: Commands,
                      gd: Res<GameData>,
                      tiles: Res<TileAssets>,
                      mut map: ResMut<Map>,
                      mut plot: ResMut<game::PlotQuest>,
                      mut ps: ResMut<PlayerState>,
                      mut inv: ResMut<Inventory>,
                      mut created: ResMut<crate::item::CreatedArtifacts>,
                      mut log: ResMut<MessageLog>| {
                    let mut rng = crate::rng::current();
                    game::populate_level(
                        &mut commands,
                        &gd,
                        &tiles,
                        &mut map,
                        &crate::map::VaultSpawns::default(),
                        7,
                        9,
                        (30, 15),
                        &mut created.0,
                        &mut inv,
                        &mut plot,
                        &mut ps,
                        &mut rng,
                        &mut log,
                    );
                },
            )
            .unwrap();
        assert_eq!(world.resource::<PlayerState>().relic_depth, 0);
        let mut q = world.query::<&crate::item::FloorItem>();
        assert!(q.iter(&world).all(|f| f
            .stack
            .iter()
            .all(|it| it.inscription != "quest")));
    }

