    #[test]
    fn random_quest_types_and_descriptions_follow_q_rand() {
        let gd = load_game_data();
        let mut rng = crate::rng::new_seeded_rng(3);
        let mut plot = game::PlotQuest::default();
        plot.init_random_quests(&gd, 20, &mut rng);
        assert_eq!(plot.rands.len(), 20);
        // is_randhero (q_rand.cc:204): the eight lost-sword types.
        let hero_types = [20, 13, 15, 16, 9, 17, 18, 8];
        for rq in plot.rands.values() {
            assert!(rq.needed >= 1 && rq.needed <= 20, "type {}", rq.needed);
            assert_eq!(
                rq.princess,
                !hero_types.contains(&rq.needed),
                "type {}",
                rq.needed
            );
        }
        // quest_random_describe (q_rand.cc:642): the pending level's quest.
        let (depth, rq) = plot.rands.iter().next().map(|(d, r)| (*d, r.clone())).unwrap();
        let mut ps = crate::birth::make_player(&gd, "R".into(), 0, 0);
        ps.depth = depth;
        ps.dungeon = rq.dungeon;
        let text = super::random_quest_description(&gd, &plot, &ps);
        let name = &gd.monsters[rq.def].name;
        assert!(text.contains(name), "{text}");
        assert!(
            text.contains(&format!("Number: {}, Killed: 0", rq.needed)),
            "{text}"
        );
        if rq.princess {
            assert!(text.contains("Captured princess!"), "{text}");
        } else {
            assert!(text.contains("Lost sword!"), "{text}");
        }
        if rq.dungeon != 0 {
            ps.dungeon = 999;
            assert!(
                super::random_quest_description(&gd, &plot, &ps).is_empty(),
                "only the principal dungeon shows the quest"
            );
        }
    }

