    #[test]
    fn library_book_reward_follows_q_library() {
        use bevy::ecs::system::RunSystemOnce;
        let gd = load_game_data();
        // initialize_bookable_spells (q_library.cc:44): 43 ToME spells.
        let list = spell::bookable_spells(&gd);
        assert_eq!(list.len(), 43);
        assert!(list.iter().any(|s| s.name == "Manathrust"));
        assert!(list.iter().any(|s| s.name == "Drain Life"));
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(|mut ctx: ModalCtx| {
                super::library_make_book(
                    &mut ctx,
                    &[
                        "Manathrust".to_string(),
                        "Healing".to_string(),
                        "Teleport".to_string(),
                    ],
                );
            })
            .unwrap();
        let inv = world.resource::<Inventory>();
        let book = inv
            .pack
            .iter()
            .find(|it| it.spells.len() == 3)
            .expect("quest tome");
        // quest_library_finalize_book takes the three chosen slots.
        assert_eq!(book.spells, vec!["Manathrust", "Healing", "Teleport"]);
        assert_eq!(book.artifact_name, world.resource::<PlayerState>().name);
        assert_eq!(
            world.resource::<game::PlotQuest>().status(game::PLOT_LIBRARY),
            game::PLOT_REWARDED
        );
    }

    #[test]
    fn fireproof_points_and_stacks_follow_q_fireprof() {
        use bevy::ecs::system::RunSystemOnce;
        let gd = load_game_data();
        let scroll = gd.object_by_tval_sval(data::TV_SCROLL, 0).unwrap();
        let mut world = spells3_world(1, 0, &[]);
        {
            let mut plot = world.resource_mut::<game::PlotQuest>();
            plot.fireproof_points = 24;
            plot.set(game::PLOT_FIREPROOF, game::PLOT_FINISHED);
        }
        {
            let mut inv = world.resource_mut::<Inventory>();
            let mut it = item::Item::base(&gd, scroll);
            it.count = 5;
            inv.pack.push(it);
        }
        // Two of five scrolls cost one point each, the rest stays mundane
        // (q_fireprof.cc fireproof_enough_points / fireproof).
        world
            .run_system_once(|mut ctx: ModalCtx| super::fireproof_stack(&mut ctx, 0, 2))
            .unwrap();
        {
            let inv = world.resource::<Inventory>();
            assert_eq!(inv.pack[0].count, 3);
            assert!(!inv.pack[0].fireproof);
            assert!(inv.pack[1].fireproof && inv.pack[1].count == 2);
        }
        assert_eq!(
            world.resource::<game::PlotQuest>().fireproof_points,
            22
        );
        // A book costs four points; with only one left it is refused.
        world
            .run_system_once(|mut ctx: ModalCtx| {
                ctx.plot.fireproof_points = 1;
                let book = ctx.gd.object_by_tval_sval(data::TV_BOOK, 0).unwrap();
                let idx = ctx.inv.pack.len();
                ctx.inv.pack.push(item::Item::base(&ctx.gd, book));
                super::fireproof_stack(&mut ctx, idx, 1);
            })
            .unwrap();
        assert_eq!(world.resource::<game::PlotQuest>().fireproof_points, 1);
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l.contains("not have enough fireproofing material")));
        // Spending the last point marks the quest rewarded
        // (q_fireprof.cc:139-142).
        world
            .run_system_once(|mut ctx: ModalCtx| {
                let mut scroll = item::Item::base(
                    &ctx.gd,
                    ctx.gd.object_by_tval_sval(data::TV_SCROLL, 0).unwrap(),
                );
                scroll.count = 1;
                let idx = ctx.inv.pack.len();
                ctx.inv.pack.push(scroll);
                ctx.plot.fireproof_points = 1;
                super::fireproof_stack(&mut ctx, idx, 1);
            })
            .unwrap();
        assert_eq!(
            world.resource::<game::PlotQuest>().status(game::PLOT_FIREPROOF),
            game::PLOT_REWARDED
        );
    }

