    #[test]
    fn one_ring_death_hook_drops_the_ring() {
        use bevy::ecs::system::RunSystemOnce;
        let gd: &'static GameData = Box::leak(Box::new(load_game_data()));
        let sauron = gd.monster_by_name("Sauron, the Sorcerer").unwrap();
        // quest_one_death_hook (q_one.cc:266): after Galadriel's warning the
        // Ring's bearers may drop ART_POWER; 30% for Sauron.  Seed the RNG
        // until a drop happens (the odds of 60 misses are negligible).
        let mut spawned = false;
        for seed in 0..60u64 {
            let mut world = spells3_world(10, 0, &[]);
            crate::rng::set_quick_rng(seed);
            {
                let mut plot = world.resource_mut::<game::PlotQuest>();
                plot.one_taken = true;
                plot.ring_spawned = false;
            }
            world
                .run_system_once(
                    move |mut commands: Commands,
                          mut stacks: Query<(Entity, &GridPos, &mut FloorItem)>,
                          mut ps: ResMut<PlayerState>,
                          mut plot: ResMut<game::PlotQuest>,
                          mut inv: ResMut<Inventory>,
                          mut map: ResMut<Map>,
                          mut log: ResMut<MessageLog>,
                          mut created: ResMut<crate::item::CreatedArtifacts>,
                          tiles: Res<TileAssets>| {
                        let mut rng = crate::rng::current();
                        let e = commands
                            .spawn((test_monster(sauron, 5, 5), GridPos { x: 5, y: 5 }))
                            .id();
                        game::kill_monster_with_note(
                            &mut commands,
                            gd,
                            &tiles,
                            &mut stacks,
                            e,
                            sauron,
                            (5, 5),
                            None,
                            None,
                            Vec::new(),
                            0,
                            false,
                            &mut ps,
                            &mut plot,
                            &mut map,
                            -1,
                            0,
                            &mut created.0,
                            &mut inv,
                            &mut log,
                            &mut rng,
                            false,
                            None,
                        );
                    },
                )
                .unwrap();
            if world.resource::<game::PlotQuest>().ring_spawned {
                assert!(world
                    .resource::<Inventory>()
                    .pack
                    .iter()
                    .any(|it| it.artifact == 13));
                spawned = true;
                break;
            }
            // A non-bearer never drops it (the chance table is empty).
            assert!(!world
                .resource::<Inventory>()
                .pack
                .iter()
                .any(|it| it.artifact == 13));
        }
        assert!(spawned, "the One Ring never dropped in 60 seeds");
    }

    #[test]
    fn library_book_selection_follows_q_library() {
        use bevy::ecs::system::RunSystemOnce;
        fn tap(world: &mut World, key: bevy::prelude::KeyCode) {
            world
                .resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>()
                .press(key);
            world.run_system_once(super::modal_input).unwrap();
            world
                .resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>()
                .reset_all();
        }
        let gd = load_game_data();
        let mut world = spells3_world(1, 0, &[]);
        *world.resource_mut::<Modal>() = Modal::Library {
            current: 0,
            slots: Vec::new(),
        };
        let spells = spell::bookable_spells(&gd);
        // Right adds the highlighted spell once (library_quest_add_spell +
        // library_quest_book_contains_spell).
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        {
            let Modal::Library { slots, .. } = world.resource::<Modal>().clone() else {
                panic!("library modal");
            };
            assert_eq!(slots, vec![spells[0].name.clone()]);
        }
        // Three slots at most (library_quest_book_slots_left).
        fn slots(world: &World) -> Vec<String> {
            match world.resource::<Modal>() {
                Modal::Library { slots, .. } => slots.clone(),
                _ => panic!("library modal"),
            }
        }
        tap(&mut world, bevy::prelude::KeyCode::ArrowDown);
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        assert_eq!(slots(&world).len(), 2);
        tap(&mut world, bevy::prelude::KeyCode::ArrowDown);
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        assert_eq!(slots(&world).len(), 3);
        tap(&mut world, bevy::prelude::KeyCode::ArrowDown);
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        assert_eq!(slots(&world).len(), 3, "a fourth spell is refused");
        // Left removes the highlighted spell (library_quest_remove_spell;
        // current is on the refused fourth entry, so step back first).
        tap(&mut world, bevy::prelude::KeyCode::ArrowUp);
        tap(&mut world, bevy::prelude::KeyCode::ArrowLeft);
        {
            let Modal::Library { slots, .. } = world.resource::<Modal>().clone() else {
                panic!("library modal");
            };
            assert_eq!(slots.len(), 2);
        }
        // Enter with three chosen finalizes the book
        // (quest_library_finalize_book / quest_library_building).
        tap(&mut world, bevy::prelude::KeyCode::ArrowRight);
        tap(&mut world, bevy::prelude::KeyCode::Enter);
        let inv = world.resource::<Inventory>();
        let book = inv
            .pack
            .iter()
            .find(|it| it.spells.len() == 3)
            .expect("tome written");
        assert_eq!(book.spells.len(), 3);
        assert_eq!(book.artifact_name, world.resource::<PlayerState>().name);
        assert_eq!(
            world.resource::<game::PlotQuest>().status(game::PLOT_LIBRARY),
            game::PLOT_REWARDED
        );
    }

    #[test]
    fn rand_quest_turn_hook_resets_and_stamps_the_level() {
        use bevy::ecs::system::RunSystemOnce;
        let mut world = spells3_world(1, 0, &[]);
        // The qrand room is carved out of granite (q_rand.cc room_alloc /
        // place_monster_one), so the test level is solid rock.
        world.insert_resource(crate::map::blank_pub(crate::map::T_GRANITE));
        let def = world
            .resource::<GameData>()
            .monster_by_name("Bandit")
            .unwrap();
        {
            let mut plot = world.resource_mut::<game::PlotQuest>();
            plot.rands.insert(
                7,
                game::RandQuest {
                    depth: 7,
                    def,
                    needed: 5,
                    got: 5,
                    princess: true,
                    dungeon: 0,
                    princess_pos: None,
                },
            );
        }
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.depth = 7;
            ps.dungeon = 9;
        }
        world
            .run_system_once(
                move |mut commands: Commands,
                      gd: Res<GameData>,
                      tiles: Res<TileAssets>,
                      mut map: ResMut<Map>,
                      mut plot: ResMut<game::PlotQuest>,
                      mut ps: ResMut<PlayerState>,
                      mut inv: ResMut<Inventory>,
                      mut created: ResMut<crate::item::CreatedArtifacts>,
                      mut log: ResMut<MessageLog>| {
                    let mut rng = crate::rng::current();
                    game::populate_level(
                        &mut commands,
                        &gd,
                        &tiles,
                        &mut map,
                        &crate::map::VaultSpawns::default(),
                        7,
                        9,
                        (30, 15),
                        &mut created.0,
                        &mut inv,
                        &mut plot,
                        &mut ps,
                        &mut rng,
                        &mut log,
                    );
                },
            )
            .unwrap();
        let plot = world.resource::<game::PlotQuest>();
        // quest_random_turn_hook resets the counter on a fresh level.
        assert_eq!(plot.rands.get(&7).map(|rq| rq.got), Some(0));
        // quest_random_gen_hook stamped her room and recorded her cell;
        // quest_random_gen_hero_hook placed `needed` copies.
        assert!(plot.rands.get(&7).unwrap().princess_pos.is_some());
        let mut q = world.query::<&crate::game::Monster>();
        assert_eq!(q.iter(&world).filter(|m| m.def == def).count(), 5);
        // quest_random_feeling_hook's warning (q_rand.cc:466).
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l.contains("Leave me alone, stupid")));
    }

    #[test]
    fn quest_level_generation_places_library_and_fireproof_contents() {
        use bevy::ecs::system::RunSystemOnce;
        // q_library.cc quest_library_gen_hook: 4d2 liches (518) west, the
        // monastic liches (611) around them and one of each golem in the
        // middle; DF_NO_GENO is set on the level.
        let mut world = spells3_world(35, 0, &[]);
        world.insert_resource(crate::save::LevelStore::default());
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.depth = game::PLOT_DEPTH_BASE + game::PLOT_LIBRARY;
            ps.dungeon = 9;
        }
        world.run_system_once(game::setup_level).unwrap();
        let mut q = world.query::<&crate::game::Monster>();
        let ids: Vec<u32> = q
            .iter(&world)
            .map(|m| world.resource::<GameData>().monsters[m.def].id)
            .collect();
        assert!(
            ids.iter().filter(|&&d| d == 518).count() >= 4,
            "liches: {ids:?}"
        );
        assert!(ids.contains(&611), "monastic lich: {ids:?}");
        for golem in [256, 261, 367, 464] {
            assert!(ids.contains(&golem), "golem {golem}: {ids:?}");
        }
        assert_eq!(
            world.resource::<game::PlotQuest>().status(game::PLOT_LIBRARY),
            game::PLOT_TAKEN,
            "entering takes the quest"
        );

        // q_fireprof.cc fireproof_gen_hook: the marked Scroll of Fire
        // (pval2 = sval, inscribed "quest") lies in the top vault.
        let mut world = spells3_world(20, 0, &[]);
        world.insert_resource(crate::save::LevelStore::default());
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.depth = game::PLOT_DEPTH_BASE + game::PLOT_FIREPROOF;
            ps.dungeon = 9;
        }
        world.run_system_once(game::setup_level).unwrap();
        let mut q = world.query::<&crate::item::FloorItem>();
        let scroll = q
            .iter(&world)
            .flat_map(|f| f.stack.iter())
            .find(|it| it.inscription == "quest")
            .expect("quest scroll");
        assert_eq!(scroll.pval2, 48);
        assert_eq!(world.resource::<GameData>().objects[scroll.def].sval, 48);
    }

    #[test]
    fn thieves_hideout_hook_runs_on_level_transition() {
        use bevy::ecs::system::RunSystemOnce;
        // The real entry path goes through level_transition (not
        // setup_level), so the gen hook must fire there too.
        let mut world = spells3_world(30, 0, &[]);
        world.insert_resource(crate::save::LevelStore::default());
        let torch = {
            let gd = world.resource::<GameData>();
            let def = gd.object_by_name("Wooden Torch").unwrap();
            crate::item::Item::base(gd, def)
        };
        world.resource_mut::<Inventory>().pack.push(torch);
        world.resource_mut::<game::TurnState>().pending =
            Some(game::Goto::Depth(game::PLOT_DEPTH_BASE + game::PLOT_THIEVES));
        world.run_system_once(game::level_transition).unwrap();
        assert!(
            world.resource::<Inventory>().pack.is_empty(),
            "level_transition must strip the pack on entry"
        );
        assert!(
            world
                .resource::<MessageLog>()
                .lines
                .iter()
                .any(|l| l.contains("possessions have been stolen")),
            "the prison-cell message must be logged"
        );
        let mut q = world.query::<&crate::item::FloorItem>();
        assert!(
            q.iter(&world).next().is_some(),
            "the stolen pack must land in the great hall"
        );
        assert!(
            world.resource::<game::PlotQuest>().status(game::PLOT_THIEVES)
                == game::PLOT_TAKEN,
            "entering must take the quest"
        );
    }

    #[test]
    fn quest_levels_are_regenerated_not_restored() {
        use bevy::ecs::system::RunSystemOnce;
        // A save/left-over snapshot of the hideout must not be restored:
        // the original regenerates quest levels, re-running their gen hooks.
        let mut world = spells3_world(30, 0, &[]);
        world.insert_resource(crate::save::LevelStore::default());
        let (ox, oy) = {
            let gd = world.resource::<GameData>();
            crate::map::quest_map_offset(gd.quest_map(game::PLOT_THIEVES).unwrap())
        };
        let mut stale = crate::map::blank_pub(crate::map::T_FLOOR);
        stale.set_terrain(ox + 22, oy + 2, crate::map::T_PERMANENT);
        world
            .resource_mut::<crate::save::LevelStore>()
            .levels
            .insert(
                crate::save::LevelKey::Quest(game::PLOT_THIEVES),
                crate::save::LevelSnap {
                    map: stale,
                    monsters: vec![],
                    floor_items: vec![],
                    floor_gold: vec![],
                    player_pos: (4, 4),
                },
            );
        let torch = {
            let gd = world.resource::<GameData>();
            let def = gd.object_by_name("Wooden Torch").unwrap();
            crate::item::Item::base(gd, def)
        };
        world.resource_mut::<Inventory>().pack.push(torch);
        world.resource_mut::<game::TurnState>().pending =
            Some(game::Goto::Depth(game::PLOT_DEPTH_BASE + game::PLOT_THIEVES));
        world.run_system_once(game::level_transition).unwrap();
        assert!(
            world.resource::<Inventory>().pack.is_empty(),
            "stale snapshot must not short-circuit the gen hook"
        );
        assert_ne!(
            world.resource::<crate::map::Map>().terrain_at(ox + 22, oy + 2),
            crate::map::T_PERMANENT,
            "the level must be regenerated"
        );
        assert!(
            !world
                .resource::<crate::save::LevelStore>()
                .levels
                .contains_key(&crate::save::LevelKey::Quest(game::PLOT_THIEVES)),
            "quest levels are not kept in the store"
        );
    }

    /// A world wired for level_transition with a real wilderness and an
    /// empty LevelStore (town/wild keys need the w_info seed map).
    fn persistence_world() -> World {
        let mut world = spells3_world(10, 0, &[]);
        let gd = world.resource::<GameData>();
        let wilderness = game::Wilderness::new(gd, &mut crate::rng::current());
        world.insert_resource(crate::save::LevelStore {
            levels: Default::default(),
            wilderness,
        });
        world
    }

    /// A floor item carrying a note no generated item can have.
    fn marker_item(world: &World, note: u32) -> crate::item::Item {
        let gd = world.resource::<GameData>();
        let def = gd.object_by_name("Long Sword").unwrap();
        let mut it = crate::item::Item::base(gd, def);
        it.note = note;
        it
    }

    fn has_marker(world: &mut World, note: u32) -> bool {
        let mut q = world.query::<&crate::item::FloorItem>();
        q.iter(world)
            .any(|f| f.stack.iter().any(|it| it.note == note))
    }

    #[test]
    fn normal_dungeon_levels_are_regenerated_not_restored() {
        use bevy::ecs::system::RunSystemOnce;
        // save_dungeon only persists levels with a `@:<depth>:S:` extension;
        // every other dungeon level is rebuilt on entry (generate_cave).
        let mut world = persistence_world();
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(1, 5));
        world.run_system_once(game::level_transition).unwrap();
        let marker = marker_item(&world, 777_001);
        world.spawn((
            crate::item::FloorItem { stack: vec![marker] },
            GridPos { x: 20, y: 20 },
        ));
        // Leave for another depth of the same dungeon and come back.
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(1, 4));
        world.run_system_once(game::level_transition).unwrap();
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(1, 5));
        world.run_system_once(game::level_transition).unwrap();
        assert!(
            !has_marker(&mut world, 777_001),
            "a normal dungeon level must be regenerated, not restored"
        );
        assert!(
            !world
                .resource::<crate::save::LevelStore>()
                .levels
                .contains_key(&crate::save::LevelKey::Dungeon {
                    dungeon: 1,
                    depth: 5
                }),
            "normal dungeon levels are never stashed"
        );
    }

    #[test]
    fn town_floor_items_do_not_survive_re_entry() {
        use bevy::ecs::system::RunSystemOnce;
        // dun_level 0 is never persisted by save_dungeon (it returns early):
        // the fixed town map is rebuilt on every entry, shop stock lives in
        // the separate store arrays.
        let mut world = persistence_world();
        let (wx, wy) = {
            let gd = world.resource::<GameData>();
            gd.town_cell(1)
        };
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.wild_x = wx;
            ps.wild_y = wy;
        }
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Wild(wx, wy));
        world.run_system_once(game::level_transition).unwrap();
        assert_eq!(world.resource::<Map>().town, 1, "must enter Bree");
        let marker = marker_item(&world, 777_002);
        world.spawn((
            crate::item::FloorItem { stack: vec![marker] },
            GridPos { x: 20, y: 20 },
        ));
        // Leave to the world overview (also never persisted) and return.
        world.resource_mut::<TurnState>().pending = Some(game::Goto::WildMap(wx, wy));
        world.run_system_once(game::level_transition).unwrap();
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Wild(wx, wy));
        world.run_system_once(game::level_transition).unwrap();
        assert_eq!(world.resource::<Map>().town, 1, "must return to Bree");
        assert!(
            !has_marker(&mut world, 777_002),
            "town floor items must not survive re-entry"
        );
        let store = world.resource::<crate::save::LevelStore>();
        assert!(
            !store
                .levels
                .contains_key(&crate::save::LevelKey::Wild(wx, wy)),
            "wilderness/town snapshots are never kept"
        );
        assert!(
            !store.levels.contains_key(&crate::save::LevelKey::Overview),
            "the overview snapshot is never kept"
        );
    }

    #[test]
    fn mount_doom_mdm_level_is_restored() {
        use bevy::ecs::system::RunSystemOnce;
        // The shipped d_info.txt has exactly one `@:S:` row: Mount Doom's
        // `@:14:S:mdm` (mindepth 85 -> absolute depth 99).  Leaving and
        // re-entering restores it, unlike every other dungeon level.
        let mut world = persistence_world();
        {
            let gd = world.resource::<GameData>();
            assert_eq!(gd.level_save_extension(5, 99), Some("mdm"));
        }
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(5, 99));
        world.run_system_once(game::level_transition).unwrap();
        let marker = marker_item(&world, 777_003);
        world.spawn((
            crate::item::FloorItem { stack: vec![marker] },
            GridPos { x: 30, y: 20 },
        ));
        // Leave to the level above; the mdm level must be stashed.
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(5, 98));
        world.run_system_once(game::level_transition).unwrap();
        assert!(
            world
                .resource::<crate::save::LevelStore>()
                .levels
                .contains_key(&crate::save::LevelKey::Dungeon {
                    dungeon: 5,
                    depth: 99
                }),
            "the mdm level must be stashed on leave"
        );
        world.resource_mut::<TurnState>().pending = Some(game::Goto::Dungeon(5, 99));
        world.run_system_once(game::level_transition).unwrap();
        assert!(
            has_marker(&mut world, 777_003),
            "the mdm level must be restored on return"
        );
        assert!(
            !world
                .resource::<crate::save::LevelStore>()
                .levels
                .contains_key(&crate::save::LevelKey::Dungeon {
                    dungeon: 5,
                    depth: 99
                }),
            "the restored snapshot is consumed"
        );
    }

    #[test]
    fn thieves_hideout_strips_the_inventory_on_entry() {
        use bevy::ecs::system::RunSystemOnce;
        // q_thief.cc quest_thieves_gen_hook: a blow on the head, the whole
        // inventory is dropped into the great hall, cursed worn items stay.
        let mut world = spells3_world(30, 0, &[]);
        world.insert_resource(crate::save::LevelStore::default());
        let (torch, dagger) = {
            let gd = world.resource::<GameData>();
            (
                gd.object_by_name("Wooden Torch").unwrap(),
                gd.object_by_name("Dagger").unwrap(),
            )
        };
        let torch_item = {
            let gd = world.resource::<GameData>();
            crate::item::Item::base(gd, torch)
        };
        let worn_item = {
            let gd = world.resource::<GameData>();
            let mut it = crate::item::Item::base(gd, dagger);
            it.cursed = true;
            it
        };
        {
            let mut inv = world.resource_mut::<Inventory>();
            inv.pack.push(torch_item);
            inv.equip[crate::data::SLOT_WEAPON] = Some(worn_item);
        }
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.depth = game::PLOT_DEPTH_BASE + game::PLOT_THIEVES;
            ps.dungeon = 9;
        }
        world.run_system_once(game::setup_level).unwrap();
        let inv = world.resource::<Inventory>();
        assert!(inv.pack.is_empty(), "pack was not stripped");
        assert!(
            inv.equip[crate::data::SLOT_WEAPON].is_some(),
            "cursed worn item must stay equipped"
        );
        let log = world.resource::<MessageLog>();
        assert!(log.lines.iter().any(|l| l.contains("vicious blow")));
        let mut q = world.query::<&crate::item::FloorItem>();
        assert!(
            q.iter(&world)
                .any(|f| f.stack.iter().any(|it| it.def == torch)),
            "the stolen pack must be dropped on the floor"
        );
    }

    #[test]
    fn old_mage_buildings_follow_q_library_and_q_fireprof() {
        use bevy::ecs::system::RunSystemOnce;
        // quest_library_describe / quest_fireproof_describe (q_library.cc
        // tables.cc levels 35 / 20).
        let (name, level, desc) = super::plot_quest_info(game::PLOT_LIBRARY).unwrap();
        assert_eq!((name, level), ("Library quest", 35));
        assert!(desc.iter().any(|l| l.contains("Make the library safe")));
        let (name, level, desc) = super::plot_quest_info(game::PLOT_FIREPROOF).unwrap();
        assert_eq!((name, level), ("Old Mages quest", 20));
        assert!(desc.iter().any(|l| l.contains("Retrieve the strange")));

        // The Wizards Spire (store 25, action 60 -> ba 56) hands out and
        // resumes the fireproofing (q_fireprof.cc quest_fireproof_building).
        let gd = load_game_data();
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(|mut ctx: ModalCtx| {
                assert_eq!(ctx.plot.status(game::PLOT_FIREPROOF), game::PLOT_UNTAKEN);
                super::generic_building_action(&mut ctx, 25, 0);
                assert_eq!(ctx.plot.status(game::PLOT_FIREPROOF), game::PLOT_TAKEN);
                // The completed quest scroll (pval2 = sval) is turned in.
                let scroll = ctx.gd.object_by_tval_sval(data::TV_SCROLL, 48).unwrap();
                let mut it = item::Item::base(&ctx.gd, scroll);
                it.pval2 = 48;
                ctx.inv.pack.push(it);
                ctx.plot.set(game::PLOT_FIREPROOF, game::PLOT_COMPLETED);
                super::generic_building_action(&mut ctx, 25, 0);
                assert_eq!(ctx.plot.status(game::PLOT_FIREPROOF), game::PLOT_FINISHED);
                assert!(matches!(*ctx.modal, Modal::Fireproof));
                assert!(ctx.inv.pack.iter().all(|i| i.def != scroll), "scroll taken");
            })
            .unwrap();

        // The Library of Anor (store 60, action 61) offers its book
        // (q_library.cc quest_library_building).
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(|mut ctx: ModalCtx| {
                super::generic_building_action(&mut ctx, 60, 0);
                assert_eq!(ctx.plot.status(game::PLOT_LIBRARY), game::PLOT_TAKEN);
                ctx.plot.set(game::PLOT_LIBRARY, game::PLOT_COMPLETED);
                super::generic_building_action(&mut ctx, 60, 0);
                assert!(matches!(*ctx.modal, Modal::Library { .. }));
            })
            .unwrap();
    }

    #[test]
    fn device_failure_chance_follows_lua_bind() {
        use bevy::ecs::system::RunSystemOnce;
        let gd = load_game_data();
        // A wand of Fireflash: with no Magic-Device skill the minimum
        // failure is 15% (lua_bind.cc spell_chance_device; the port clamps
        // with `15 - skill_scale(DEVICE, 25)` in modal.rs use_device).
        let def = gd.object_by_tval_sval(data::TV_WAND, 4).unwrap();
        let mut saw_failure = false;
        for seed in 0..80u64 {
            let mut world = spells3_world(10, 0, &[]);
            crate::rng::set_quick_rng(seed);
            {
                let mut inv = world.resource_mut::<Inventory>();
                let mut it = item::Item::base(&gd, def);
                it.charges = 5;
                inv.pack.push(it);
            }
            world
                .run_system_once(|mut ctx: ModalCtx| {
                    let def = ctx.inv.pack[0].def;
                    super::use_device(&mut ctx, 0, def, data::TV_WAND);
                })
                .unwrap();
            if world
                .resource::<MessageLog>()
                .lines
                .iter()
                .any(|l| l.contains("failed to use the device"))
            {
                saw_failure = true;
                break;
            }
        }
        assert!(saw_failure, "device failure never rolled");
    }

    // --- modules.cc -------------------------------------------------------

    #[test]
    fn module_give_hooks_follow_modules_cc() {
        let gd = load_game_data();
        // drunk_takes_wine (modules.cc:542): Ale/Wine (TV_FOOD 38/39) given
        // to the Singing, happy drunk becomes an empty bottle.
        let drunk = gd.monster_by_name("Singing, happy drunk").expect("drunk");
        let ale = gd.object_by_tval_sval(data::TV_FOOD, 38).expect("ale");
        let bottle = game::drunk_takes_wine(&gd, drunk, &item::Item::base(&gd, ale))
            .expect("empty bottle");
        assert_eq!(gd.objects[bottle.def].tval, data::TV_BOTTLE);
        let apple = gd
            .objects
            .iter()
            .position(|o| o.tval == data::TV_FOOD && o.sval != 38 && o.sval != 39)
            .expect("other food");
        assert!(game::drunk_takes_wine(&gd, drunk, &item::Item::base(&gd, apple)).is_none());
        // The other give hooks key on these monster names (input.rs
        // hobbit_food / smeagol_ring).
        assert!(gd.monster_by_name("Scruffy-looking hobbit").is_some());
        assert!(gd.monster_by_name("Smeagol").is_some());
    }

    // --- powers.cc --------------------------------------------------------

    #[test]
    fn power_chance_and_activate_follow_powers_cc() {
        use bevy::ecs::system::RunSystemOnce;

        // power_chance: the level gate refuses 61 (Balrog, level 35) and
        // spends no energy (powers.cc:64).
        let mut world = spells3_world(1, 0, &[]);
        world
            .run_system_once(|mut ctx: ModalCtx| power_use(&mut ctx, 61, false))
            .unwrap();
        assert!(!world.resource::<TurnState>().world_turn);
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l == "You need to attain level 35 to use this power."));

        // power_chance: confusion refuses the power (powers.cc:72).
        let mut world = spells3_world(50, 0, &[]);
        world.resource_mut::<PlayerState>().confuse = 3;
        world
            .run_system_once(|mut ctx: ModalCtx| power_use(&mut ctx, 44, false))
            .unwrap();
        assert!(!world.resource::<TurnState>().world_turn);
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l == "You are too confused to use this power."));

        // A successful power spends the turn and runs its activation
        // (power_activate: PWR_WRECK_WORLD flags the level rebuild).
        let mut world = spells3_world(50, 0, &[]);
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.stats[crate::game::CHA] = 32000;
            ps.mana = ps.max_mana;
        }
        world
            .run_system_once(|mut ctx: ModalCtx| power_use(&mut ctx, 44, false))
            .unwrap();
        assert!(world.resource::<TurnState>().world_turn);
        assert!(world.resource::<TurnState>().regen_level);
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l == "The world changes!"));

        // A zero-cost power skips the whole stat roll ("Always true ?",
        // powers.cc:51) but still activates (PWR_DODGE at level 1).
        let mut world = spells3_world(1, 0, &[]);
        let before_mana = world.resource::<PlayerState>().mana;
        world
            .run_system_once(|mut ctx: ModalCtx| power_use(&mut ctx, 60, false))
            .unwrap();
        assert!(world.resource::<TurnState>().world_turn);
        assert_eq!(world.resource::<PlayerState>().mana, before_mana);
    }

    #[test]
    fn power_selection_and_do_cmd_power_use_the_modal() {
        use bevy::ecs::system::RunSystemOnce;
        fn tap(world: &mut World, key: bevy::prelude::KeyCode) {
            world
                .resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>()
                .press(key);
            world.run_system_once(super::modal_input).unwrap();
            world
                .resource_mut::<bevy::prelude::ButtonInput<bevy::prelude::KeyCode>>()
                .reset_all();
        }
        let mut world = spells3_world(50, 0, &[]);
        {
            let mut ps = world.resource_mut::<PlayerState>();
            ps.stats[crate::game::CHA] = 32000;
            ps.mana = ps.max_mana;
            // available_powers sorts the ids: [44, 60].
            ps.extra_powers = vec![60, 44];
        }
        // select_power keeps the highlighted index inside the list and
        // wraps with the arrow keys.
        *world.resource_mut::<Modal>() = Modal::Powers { cursor: 0 };
        tap(&mut world, bevy::prelude::KeyCode::ArrowDown);
        assert!(*world.resource::<Modal>() == Modal::Powers { cursor: 1 });
        tap(&mut world, bevy::prelude::KeyCode::ArrowUp);
        assert!(*world.resource::<Modal>() == Modal::Powers { cursor: 0 });
        // Enter runs do_cmd_power on the highlighted power (44).
        tap(&mut world, bevy::prelude::KeyCode::Enter);
        assert!(world.resource::<TurnState>().world_turn);
        assert!(world.resource::<TurnState>().regen_level);
        assert!(*world.resource::<Modal>() == Modal::None);
        // Escape leaves the selector without using anything.
        *world.resource_mut::<Modal>() = Modal::Powers { cursor: 0 };
        let turn = world.resource::<TurnState>().world_turn;
        tap(&mut world, bevy::prelude::KeyCode::Escape);
        assert!(*world.resource::<Modal>() == Modal::None);
        assert_eq!(world.resource::<TurnState>().world_turn, turn);

        // An empty power list closes with the original message
        // (powers.cc:1124), spending no turn.
        let mut world = spells3_world(1, 0, &[]);
        world.resource_mut::<PlayerState>().extra_powers.clear();
        *world.resource_mut::<Modal>() = Modal::Powers { cursor: 0 };
        tap(&mut world, bevy::prelude::KeyCode::ArrowDown);
        assert!(*world.resource::<Modal>() == Modal::None);
        assert!(world
            .resource::<MessageLog>()
            .lines
            .iter()
            .any(|l| l == "You don't have any special powers."));
    }

